function getVehicleIcon(type) {
  switch (type) {
    case 'عربية':
    case 'car':
      return 'ri-car-fill';
    case 'اسكوتر':
    case 'scooter':
      return 'ri-e-bike-2-fill';
    case 'موتوسيكل':
    case 'motorcycle':
      return 'ri-motorbike-fill';
    default:
      return 'ri-car-fill';
  }
}

function formatAppUsageDuration(totalSeconds) {
  const secs = parseInt(totalSeconds || 0);
  if (!secs || secs < 60) {
    return secs > 0 ? `${secs} ثانية` : 'أقل من دقيقة';
  }
  const minutes = Math.floor(secs / 60);
  if (minutes < 60) {
    return `${minutes} دقيقة`;
  }
  const hours = Math.floor(minutes / 60);
  const remMinutes = minutes % 60;
  if (remMinutes === 0) {
    return `${hours} ${hours === 1 ? 'ساعة' : (hours === 2 ? 'ساعتان' : (hours <= 10 ? 'ساعات' : 'ساعة'))}`;
  }
  return `${hours} س و ${remMinutes} د`;
}

function formatLastOpenedDateTime(dateStrOrObj) {
  if (!dateStrOrObj) return 'لم يفتح بعد';
  try {
    const d = new Date(dateStrOrObj);
    if (isNaN(d.getTime())) return 'لم يفتح بعد';
    const now = new Date();
    const isToday = d.toDateString() === now.toDateString();
    const yesterday = new Date(now);
    yesterday.setDate(yesterday.getDate() - 1);
    const isYesterday = d.toDateString() === yesterday.toDateString();

    const timeStr = d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
    if (isToday) {
      return `اليوم ${timeStr}`;
    }
    if (isYesterday) {
      return `أمس ${timeStr}`;
    }
    const dayName = d.toLocaleDateString('ar-EG', { weekday: 'short', day: 'numeric', month: 'short' });
    return `${dayName} ${timeStr}`;
  } catch (_) {
    return 'غير متاح';
  }
}

function formatHeartbeatTime(dateStrOrMs) {
  if (!dateStrOrMs) return 'لا يوجد نبض';
  try {
    const d = new Date(dateStrOrMs);
    if (isNaN(d.getTime())) return 'لا يوجد نبض';
    const diffSec = Math.floor((Date.now() - d.getTime()) / 1000);
    if (diffSec < 0) return 'الآن (نشط 🟢)';
    if (diffSec < 45) return 'الآن (نشط 🟢)';
    if (diffSec < 60) return `منذ ${diffSec} ثانية`;
    const diffMin = Math.floor(diffSec / 60);
    if (diffMin < 60) return `منذ ${diffMin} دقيقة`;
    return formatLastOpenedDateTime(d);
  } catch (_) {
    return 'غير متاح';
  }
}

function getDriverTimeoutSeconds() {
  const cfg = mockData?.settings?.driver_offline_timeout_seconds;
  return Math.max(30, parseInt(cfg) || 180);
}

function isDriverCurrentlyOnline(drvObj, userObj) {
  if (!drvObj && !userObj) return false;
  const timeoutSec = getDriverTimeoutSeconds();
  const lastSeenVal = drvObj?.last_seen_at || userObj?.last_seen_at;
  if (lastSeenVal) {
    const lastSeenMs = new Date(lastSeenVal).getTime();
    if (!isNaN(lastSeenMs)) {
      const diffSec = (Date.now() - lastSeenMs) / 1000;
      return diffSec <= timeoutSec;
    }
  }
  return (drvObj?.is_online === true || drvObj?.is_app_open === true || userObj?.is_app_open === true);
}

function isDriverAvailableForTrips(drvObj) {
  if (!drvObj) return false;
  return drvObj.is_available === true;
}

function isUserCurrentlyOnline(userObj, fallbackIsOnline = false) {
  if (!userObj) return !!fallbackIsOnline;
  const timeoutSec = getDriverTimeoutSeconds();
  if (userObj.last_seen_at) {
    const lastSeenMs = new Date(userObj.last_seen_at).getTime();
    if (!isNaN(lastSeenMs)) {
      const diffSec = (Date.now() - lastSeenMs) / 1000;
      return diffSec <= timeoutSec;
    }
  }
  return userObj.is_app_open === true || !!fallbackIsOnline;
}

function getStatusClass(status) {
  switch (status) {
    case 'مكتملة':
    case 'Completed':
      return 'completed';
    case 'ملغاة':
    case 'Cancelled':
      return 'cancelled';
    case 'جارية':
    case 'Searching':
    case 'Accepted':
    case 'DriverArriving':
    case 'TripStarted':
      return 'active';
    case 'verified':
    case 'معتمد':
      return 'verified';
    case 'submitted':
    case 'قيد المراجعة':
      return 'submitted';
    case 'unregistered':
    case 'غير مسجل':
      return 'unregistered';
    case 'نشط':
    case 'active':
      return 'completed';
    case 'غير نشط':
    case 'inactive':
      return 'cancelled';
    default:
      return 'pending';
  }
}

function animateCounter(element, target, duration = 1200) {
  let start = 0;
  const startTime = performance.now();

  function update(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
    const current = Math.round(start + (target - start) * eased);

    element.textContent = current.toLocaleString('ar-EG');

    if (progress < 1) {
      requestAnimationFrame(update);
    }
  }

  requestAnimationFrame(update);
}

function initDashboardAnimations() {
  setTimeout(() => {
    document.querySelectorAll('.stat-card-value[data-target]').forEach(el => {
      const target = parseInt(el.dataset.target || '0', 10);
      if (!isNaN(target)) {
        animateCounter(el, target);
      }
    });
  }, 300);
}

// ============================================
// NAVIGATION
// ============================================

function navigateTo(page) {
  const validPages = ['security', 'promos', 'rewards', 'dashboard', 'trips', 'drivers', 'passengers', 'ratings', 'driver-profile', 'passenger-profile', 'wallet', 'pricing', 'places', 'banners', 'communication', 'messages', 'support', 'reports', 'content', 'monitoring', 'logs', 'settings'];
  if (!validPages.includes(page)) {
    page = 'dashboard';
  }

  currentPage = page;
  sessionStorage.setItem('admin_currentPage', page);
  if (page === 'driver-profile' || page === 'passenger-profile') {
    sessionStorage.setItem('admin_activeProfileUid', activeProfileUid);
    sessionStorage.setItem('admin_activeProfileRole', activeProfileRole);
  } else {
    sessionStorage.removeItem('admin_activeProfileUid');
    sessionStorage.removeItem('admin_activeProfileRole');
  }

  // Update active nav item
  document.querySelectorAll('.nav-item').forEach(item => {
    item.classList.remove('active');
    if (item.dataset.page === page) {
      item.classList.add('active');
    }
  });

  // Update header title
  updateHeaderTitle(page);

  // Render page content
  renderPage(page);

  // Close mobile sidebar
  closeSidebar();
}

