async function sendPushNotificationBackend({ recipientId, title, body, type = 'driver_status', targetRole = '' }) {
  console.log(`[PushNotificationLog] Sending push to ${recipientId} | Title: "${title}" | Body: "${body}" | TargetRole: "${targetRole}"`);
  try {
    if (supabaseClient && recipientId) {
      await supabaseClient.from('notifications').insert({
        id: generateUUID(),
        user_id: recipientId,
        title: title,
        body: body,
        type: type,
        is_read: false,
        created_at: new Date().toISOString(),
        data: { recipientId, title, body, type, target_role: targetRole }
      });
    }

    await dispatchDashboardPushNotification({
      target: 'specific',
      recipientId: recipientId,
      title: title,
      body: body,
      type: type,
      adminNotificationId: generateUUID()
    });
  } catch (err) {
    console.error('[PushNotificationLog] Error sending push notification:', err);
  }
}

function approveDriver(driverUidOrId) {
  const driver = mockData.drivers.find(d => d.uid === driverUidOrId || d.id === driverUidOrId);
  const targetUid = driver ? driver.uid : driverUidOrId;
  const driverName = driver ? driver.name : 'السائق';

  if (!targetUid) {
    showToast('❌ لم يتم العثور على كود السائق');
    return;
  }

  const prevStatus = driver ? driver.status : null;
  const prevStatusAr = driver ? driver.statusAr : null;
  const prevReason = driver ? driver.rejectionReason : null;

  const approveTitle = "Your driver account has been approved.";
  const approveBody = "Congratulations! Your driver account has been approved. You can now start accepting trips.";

  // 1. Optimistic immediate update
  if (driver) {
    driver.status = 'verified';
    driver.statusAr = 'معتمد';
    driver.rejectionReason = '';
  }
  updatePendingBadge();
  renderPage(currentPage);
  showToast(`✅ تم اعتماد السائق ${driverName} بنجاح`);

  const modal = document.querySelector('.modal-backdrop');
  if (modal) modal.remove();

  if (supabaseClient) {
    supabaseClient.from('drivers')
      .update({ verification_status: 'verified', rejection_reason: null, updated_at: new Date().toISOString() })
      .eq('id', targetUid)
      .then(async ({ error }) => {
        if (!error) {
          await sendPushNotificationBackend({
            recipientId: targetUid,
            title: approveTitle,
            body: approveBody,
            type: 'driver_approved'
          });
          if (typeof window.runBulkSync === 'function') {
            window.runBulkSync();
          }
        } else {
          if (driver) {
            driver.status = prevStatus;
            driver.statusAr = prevStatusAr;
            driver.rejectionReason = prevReason;
            updatePendingBadge();
            renderPage(currentPage);
          }
          showToast(`❌ فشل الاعتماد: ${error.message}`);
        }
      }).catch(err => {
        if (driver) {
          driver.status = prevStatus;
          driver.statusAr = prevStatusAr;
          driver.rejectionReason = prevReason;
          updatePendingBadge();
          renderPage(currentPage);
        }
        showToast(`❌ فشل الاعتماد: ${err.message}`);
      });
  }
}

