function confirmRejectDriver(driverUid) {
  const reasonInput = document.getElementById('rejectionReasonInput');
  const rejectionReason = reasonInput ? reasonInput.value.trim() : '';

  const driver = mockData.drivers.find(d => d.uid === driverUid || d.id === driverUid);
  const driverName = driver ? driver.name : 'السائق';

  const prevStatus = driver ? driver.status : null;
  const prevStatusAr = driver ? driver.statusAr : null;
  const prevReason = driver ? driver.rejectionReason : null;

  const rejectTitle = "Driver application rejected.";
  const rejectBody = rejectionReason ? `Driver application rejected: ${rejectionReason}` : "Driver application rejected.";

  // 1. Optimistic immediate update
  if (driver) {
    driver.status = 'rejected';
    driver.statusAr = 'مرفوض';
    driver.rejectionReason = rejectionReason;
  }
  updatePendingBadge();
  renderPage(currentPage);
  showToast(`❌ تم رفض طلب السائق ${driverName}`);

  const modal = document.querySelector('.modal-backdrop');
  if (modal) modal.remove();

  if (supabaseClient) {
    supabaseClient.from('drivers')
      .update({ verification_status: 'rejected', rejection_reason: rejectionReason, updated_at: new Date().toISOString() })
      .eq('id', driverUid)
      .then(async ({ error }) => {
        if (!error) {
          await sendPushNotificationBackend({
            recipientId: driverUid,
            title: rejectTitle,
            body: rejectBody,
            type: 'driver_rejected'
          });
          if (typeof window.runBulkSync === 'function') {
            window.runBulkSync();
          }
        } else {
          if (driver) {
            driver.status = prevStatus;
            driver.statusAr = prevStatusAr;
            driver.rejectionReason = prevReason;
            updatePendingBadge();
            renderPage(currentPage);
          }
          showToast(`❌ فشل عملية الرفض: ${error.message}`);
        }
      }).catch(err => {
        if (driver) {
          driver.status = prevStatus;
          driver.statusAr = prevStatusAr;
          driver.rejectionReason = prevReason;
          updatePendingBadge();
          renderPage(currentPage);
        }
        showToast(`❌ فشل عملية الرفض: ${err.message}`);
      });
  }
}

function parseVehicleImages(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) {
    return raw.filter(item => typeof item === 'string' && item.trim().length > 5 && !item.includes('placehold.co'));
  }
  if (typeof raw === 'string') {
    const trimmed = raw.trim();
    if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) {
          return parsed.filter(item => typeof item === 'string' && item.trim().length > 5 && !item.includes('placehold.co'));
        }
      } catch (_) { }
    }
    if (trimmed.includes(',')) {
      return trimmed.split(',')
        .map(s => s.trim().replace(/^["']|["']$/g, ''))
        .filter(s => s.length > 5 && !s.includes('placehold.co'));
    }
    if (trimmed.length > 5 && !trimmed.includes('placehold.co')) {
      return [trimmed];
    }
  }
  return [];
}

