async function resolveSupportTicket(ticketId) {
  if (!ticketId) return;

  if (supabaseClient) {
    try {
      const { error } = await supabaseClient
        .from('support_chats')
        .update({
          status: 'resolved',
          updated_at: new Date().toISOString()
        })
        .eq('id', ticketId);

      if (!error) {
        showToast('✅ تم إغلاق وحل الشكوى بنجاح (ستختفي من تطبيق العميل وستظل محفوظة بالداش بورد)');
        await loadSupportChatsFromSupabase();
        const container = document.getElementById('pageContent');
        if (container) container.innerHTML = renderCommunication();
      } else {
        showToast(`❌ فشل إغلاق الشكوى: ${error.message}`);
      }
    } catch (e) {
      showToast(`❌ خطأ: ${e.message}`);
    }
  } else {
    showToast('✅ تم إغلاق وحل الشكوى محلياً');
  }
}

let liveRideChats = [];
let activeRideChatRoomId = null;

async function loadRideChatsFromSupabase() {
  if (!supabaseClient) return [];

  try {
    const { data: rides } = await supabaseClient
      .from('ride_requests')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(30);

    if (rides && rides.length > 0) {
      const pIds = rides.map(r => r.passenger_id).filter(Boolean);
      const dIds = rides.map(r => r.driver_id).filter(Boolean);

      let pMap = {}, dMap = {};

      if (pIds.length > 0) {
        const { data: pUsers } = await supabaseClient.from('users').select('id, name, phone_number').in('id', pIds);
        (pUsers || []).forEach(u => { pMap[u.id] = { name: u.name || 'راكب', phone: u.phone_number || '—' }; });
      }

      if (dIds.length > 0) {
        const { data: dUsers } = await supabaseClient.from('drivers').select('id, user_id, name, phone_number').in('id', dIds);
        (dUsers || []).forEach(d => {
          const key = d.user_id || d.id;
          dMap[key] = { name: d.name || 'كابتن', phone: d.phone_number || '—' };
          dMap[d.id] = { name: d.name || 'كابتن', phone: d.phone_number || '—' };
        });
      }

      liveRideChats = rides.map(r => {
        const pInfo = pMap[r.passenger_id] || {};
        const dInfo = dMap[r.driver_id] || {};
        return {
          id: r.id,
          trip_id: r.id,
          passenger_id: r.passenger_id,
          driver_id: r.driver_id,
          passenger_name: pInfo.name || r.passenger_name || 'راكب',
          passenger_phone: pInfo.phone || r.passenger_phone || '—',
          driver_name: dInfo.name || r.driver_name || 'كابتن',
          driver_phone: dInfo.phone || r.driver_phone || '—',
          pickup: r.pickup_address || 'نقطة الانطلاق',
          destination: r.destination_address || 'الوجهة',
          status: r.status || 'completed',
          updated_at: r.created_at
        };
      });
    } else {
      liveRideChats = [];
    }

    const container = document.getElementById('rideChatsListContainer');
    if (container) container.innerHTML = renderRideChatsListHtml();
    return liveRideChats;
  } catch (e) {
    console.warn('[Comm] Warning loading ride chats:', e);
    return [];
  }
}

function renderRideChatsListHtml() {
  if (!liveRideChats || liveRideChats.length === 0) {
    return `<div style="text-align:center;padding:32px;color:var(--text-light);font-size:12px;">لا توجد محادثات رحلات مسجلة بالنظام حالياً.</div>`;
  }

  return liveRideChats.map(room => {
    const isSelected = activeRideChatRoomId === room.id;
    const dateStr = room.updated_at ? new Date(room.updated_at).toLocaleString('ar-EG') : 'الآن';
    const statusBg = room.status === 'active' ? '#D1FAE5' : '#E2E8F0';
    const statusColor = room.status === 'active' ? '#065F46' : '#475569';
    const statusText = room.status === 'active' ? 'جارية 🚗' : 'مكتملة ✅';

    return `
      <div onclick="selectRideChatRoom('${room.id}')" style="padding:14px;border-bottom:1px solid var(--border-light);cursor:pointer;background:${isSelected ? 'rgba(30,136,229,0.08)' : 'transparent'};transition:all 0.2s;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
          <strong style="font-size:13px;color:var(--text-primary);">رحلة #${(room.trip_id || room.id).substring(0, 8).toUpperCase()}</strong>
          <span class="badge" style="background:${statusBg};color:${statusColor};font-size:10px;padding:2px 8px;border-radius:10px;">${statusText}</span>
        </div>
        <div style="font-size:12px;color:var(--text-secondary);display:flex;flex-direction:column;gap:3px;">
          <div>👤 <strong>الراكب:</strong> ${room.passenger_name || 'راكب'} (${room.passenger_phone || '—'})</div>
          <div>🚗 <strong>الكابتن:</strong> ${room.driver_name || 'كابتن'} (${room.driver_phone || '—'})</div>
        </div>
        <div style="font-size:10.5px;color:var(--text-light);margin-top:6px;display:flex;justify-content:space-between;">
          <span>📍 ${room.pickup || 'الموقع'} ➔ ${room.destination || 'الوجهة'}</span>
          <span>${dateStr}</span>
        </div>
      </div>
    `;
  }).join('');
}

function selectRideChatRoom(roomId) {
  activeRideChatRoomId = roomId;
  const container = document.getElementById('rideChatsListContainer');
  if (container) container.innerHTML = renderRideChatsListHtml();
  loadRideChatMessages(roomId);
}

async function loadRideChatMessages(roomId) {
  const mainPanel = document.getElementById('rideChatMainPanel');
  if (!mainPanel || !roomId) return;

  const room = liveRideChats.find(r => r.id === roomId);
  const tripTitle = room ? `#${(room.trip_id || room.id).substring(0, 8).toUpperCase()}` : 'الرحلة';

  mainPanel.innerHTML = `
    <div style="padding:16px;border-bottom:1px solid var(--border-color);background:var(--bg-primary);display:flex;justify-content:space-between;align-items:center;">
      <div>
        <h4 style="margin:0;font-size:15px;font-weight:700;">محادثة الرحلة ${tripTitle}</h4>
        <div style="font-size:11.5px;color:var(--text-secondary);margin-top:2px;">
          👤 الراكب: ${room?.passenger_name || '—'} (${room?.passenger_phone || '—'}) • 🚗 الكابتن: ${room?.driver_name || '—'} (${room?.driver_phone || '—'})
        </div>
      </div>
      <span class="badge" style="background:#E0F2FE;color:#0369A1;font-weight:700;">تنسيق موثق inRide</span>
    </div>
    <div id="rideChatMessagesBox" style="padding:20px;overflow-y:auto;min-height:380px;max-height:500px;display:flex;flex-direction:column;gap:12px;">
      <div style="text-align:center;color:var(--text-light);padding:30px;">
        <i class="ri-loader-4-line ri-spin" style="font-size:24px;"></i>
        <div>جاري تحميل سِجل محادثة الرحلة الحقيقي...</div>
      </div>
    </div>
  `;

  let msgs = [];

  if (supabaseClient) {
    try {
      const { data: realMsgs } = await supabaseClient
        .from('messages')
        .select('*')
        .or(`room_id.eq.${roomId},trip_id.eq.${roomId}`)
        .order('created_at', { ascending: true });

      if (realMsgs && realMsgs.length > 0) {
        msgs = realMsgs.map(m => ({
          sender: (m.sender_id === room?.passenger_id || m.sender_type === 'rider') ? 'passenger' : 'driver',
          text: m.content || m.text || m.message || '',
          time: m.created_at ? new Date(m.created_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' }) : 'الآن'
        }));
      }
    } catch (_) { }
  }

  const box = document.getElementById('rideChatMessagesBox');
  if (box) {
    if (msgs.length === 0) {
      box.innerHTML = `
        <div style="text-align:center;padding:40px;color:var(--text-light);font-size:13px;">
          <i class="ri-chat-delete-line" style="font-size:36px;display:block;margin-bottom:8px;color:var(--medium-blue);"></i>
          لا توجد رسائل نصية متبادلة بين الكابتن والراكب في هذه الرحلة حتى الآن.
        </div>`;
    } else {
      box.innerHTML = msgs.map(m => `
        <div style="display:flex;flex-direction:column;align-items:${m.sender === 'passenger' ? 'flex-end' : 'flex-start'};">
          <div style="background:${m.sender === 'passenger' ? 'var(--medium-blue)' : '#F1F5F9'};color:${m.sender === 'passenger' ? 'white' : 'var(--text-primary)'};padding:10px 14px;border-radius:14px;max-width:70%;font-size:13px;">
            ${m.text}
          </div>
          <span style="font-size:10px;color:var(--text-light);margin-top:2px;">${m.sender === 'passenger' ? '👤 الراكب' : '🚗 الكابتن'} • ${m.time}</span>
        </div>
      `).join('');
    }
    box.scrollTop = box.scrollHeight;
  }
}

function setCommRoleFilter(role) {
  commRoleFilter = role;
  renderCommConversationsList();
}

function onCommSearchInput(query) {
  commSearchQuery = (query || '').toLowerCase().trim();
  renderCommConversationsList();
}

function selectCommConversation(userId, role) {
  if (commActiveUserId === userId) return;
  commActiveUserId = userId;
  commActiveUserRole = role || 'rider';

  const items = document.querySelectorAll('.comm-conv-item');
  items.forEach(item => {
    if (item.getAttribute('data-userid') === userId) {
      item.classList.add('active');
    } else {
      item.classList.remove('active');
    }
  });

  loadCommMessagesThread(userId, true);
}

function openDirectUserChat(userId, userName, role) {
  commActiveUserId = userId;
  commActiveUserRole = role || 'rider';
  currentCommunicationTab = 'chat';
  const container = document.getElementById('pageContent');
  if (container) {
    if (currentPage !== 'communication') {
      navigateTo('communication');
    } else {
      container.innerHTML = renderCommunication();
      initCommChatSync();
      loadCommMessagesThread(userId, true);
    }
  }
}

function getCommContactsList() {
  let contactsMap = {};

  if (mockData.drivers) {
    mockData.drivers.forEach(d => {
      contactsMap[d.uid] = {
        id: d.uid,
        name: d.name || 'كابتن',
        phone: d.phone || '',
        role: 'driver',
        roleAr: 'كابتن 🚗',
        rating: (parseFloat(d.rating) || 5.0).toFixed(1),
        avatar: (d.name || 'ك').charAt(0),
        lastMessage: 'بدء محادثة مباشرة مع الكابتن',
        lastTime: d.joinDate || 'الآن',
        lastTimestamp: 0,
        unread: 0
      };
    });
  }

  if (mockData.passengers) {
    mockData.passengers.forEach(p => {
      contactsMap[p.uid] = {
        id: p.uid,
        name: p.name || 'راكب',
        phone: p.phone || '',
        role: 'rider',
        roleAr: 'راكب 👤',
        rating: (parseFloat(p.rating) || 5.0).toFixed(1),
        avatar: (p.name || 'ر').charAt(0),
        lastMessage: 'بدء محادثة مباشرة مع الراكب',
        lastTime: p.joinDate || 'الآن',
        lastTimestamp: 0,
        unread: 0
      };
    });
  }

  // Merge live support chats from Supabase
  if (liveSupportChats && liveSupportChats.length > 0) {
    liveSupportChats.forEach(chat => {
      const uId = chat.id || chat.user_id;
      if (!uId) return;

      const timeStr = chat.last_message_at ? new Date(chat.last_message_at).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' }) : 'الآن';
      const ts = chat.last_message_at ? new Date(chat.last_message_at).getTime() : Date.now();
      const isDriver = chat.user_type === 'driver';

      if (contactsMap[uId]) {
        contactsMap[uId].lastMessage = chat.last_message || contactsMap[uId].lastMessage;
        contactsMap[uId].lastTime = timeStr;
        contactsMap[uId].lastTimestamp = ts;
        if (chat.user_name) contactsMap[uId].name = chat.user_name;
        if (chat.unread_admin_count) contactsMap[uId].unread = chat.unread_admin_count;
      } else {
        contactsMap[uId] = {
          id: uId,
          name: chat.user_name || (isDriver ? 'كابتن inRide' : 'مستخدم inRide'),
          phone: chat.phone || '',
          role: isDriver ? 'driver' : 'rider',
          roleAr: isDriver ? 'كابتن 🚗' : 'راكب 👤',
          rating: '5.0',
          avatar: (chat.user_name || 'م').charAt(0),
          lastMessage: chat.last_message || 'رسالة جديدة من التطبيق',
          lastTime: timeStr,
          lastTimestamp: ts,
          unread: chat.unread_admin_count || 0
        };
      }
    });
  }

  let contacts = Object.values(contactsMap);
  contacts.sort((a, b) => (b.lastTimestamp || 0) - (a.lastTimestamp || 0));
  return contacts;
}

function renderCommConversationsListHtml() {
  const contacts = getCommContactsList();

  // Filter contacts
  const filtered = contacts.filter(c => {
    if (commRoleFilter === 'driver' && c.role !== 'driver') return false;
    if (commRoleFilter === 'rider' && c.role !== 'rider') return false;

    if (commSearchQuery) {
      const q = commSearchQuery.toLowerCase();
      const n = (c.name || '').toString().toLowerCase();
      const p = (c.phone || '').toString().toLowerCase();
      if (!n.includes(q) && !p.includes(q)) return false;
    }
    return true;
  });

  if (filtered.length === 0) {
    return `
      <div style="text-align:center;padding:30px;color:var(--text-light);font-size:12px;">
        <i class="ri-search-line" style="font-size:24px;display:block;margin-bottom:6px;"></i>
        لا يوجد مستخدمون يطابقون خيارات البحث
      </div>`;
  }

  return filtered.map(c => {
    const isActive = commActiveUserId === c.id;
    const cacheMsgs = commMessagesCache[c.id];
    let previewText = c.lastMessage;
    if (cacheMsgs && cacheMsgs.length > 0) {
      previewText = cacheMsgs[cacheMsgs.length - 1].text || previewText;
    }

    return `
      <div class="comm-conv-item ${isActive ? 'active' : ''}" data-userid="${c.id}" onclick="selectCommConversation('${c.id}', '${c.role}')">
        <div class="comm-avatar ${c.role === 'driver' ? 'driver' : ''}">
          ${c.avatar}
          <div class="comm-avatar-badge"></div>
        </div>
        <div class="comm-conv-info">
          <div class="comm-conv-top">
            <span class="comm-conv-name">${c.name}</span>
            <span class="comm-conv-time">${c.lastTime}</span>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span class="comm-conv-preview" style="max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${previewText}</span>
            <div style="display:flex;align-items:center;gap:4px;">
              ${c.unread > 0 ? `<span class="badge" style="background:#EF4444;color:white;font-size:10px;">${c.unread}</span>` : ''}
              <span class="badge" style="font-size:10px;padding:2px 6px;background:${c.role === 'driver' ? '#E0F2FE' : '#F3E8FF'};color:${c.role === 'driver' ? '#0369A1' : '#7E22CE'}; font-weight:700;">
                ${c.roleAr}
              </span>
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function renderCommChatPanelHtml(userId) {
  if (!userId) {
    return `
      <div style="text-align:center;padding:60px 20px;color:var(--text-light);">
        <i class="ri-chat-smile-2-line" style="font-size:48px;display:block;margin-bottom:12px;"></i>
        <h4 style="margin:0 0 6px 0;">اختر محادثة لبدء التواصل</h4>
        <p style="font-size:12px;margin:0;">يمكنك إرسال رسائل مباشرة لأي كابتن أو راكب مسجل بالنظام</p>
      </div>
    `;
  }

  let userObj = null;
  if (mockData.drivers) userObj = mockData.drivers.find(d => d.uid === userId);
  if (!userObj && mockData.passengers) userObj = mockData.passengers.find(p => p.uid === userId);
  if (!userObj && liveSupportChats) {
    const sChat = liveSupportChats.find(c => (c.id || c.user_id) === userId);
    if (sChat) {
      userObj = {
        name: sChat.user_name,
        phone: sChat.phone,
        vehicleType: sChat.user_type === 'driver' ? 'car' : null,
        rating: '5.0'
      };
    }
  }

  const userName = userObj ? userObj.name : 'مستخدم';
  const userPhone = userObj ? (userObj.phone || '—') : '—';
  const isDriver = commActiveUserRole === 'driver' || (userObj && userObj.vehicleType);
  const ratingVal = userObj ? (parseFloat(userObj.rating) || 5.0).toFixed(1) : '5.0';
  const roleText = isDriver ? 'كابتن 🚗' : 'راكب 👤';

  const cachedList = commMessagesCache[userId];
  let messagesHtml = '';

  if (cachedList && cachedList.length > 0) {
    messagesHtml = cachedList.map(m => {
      const isAdmin = m.sender === 'admin';
      const bg = isAdmin ? '#E0F2FE' : '#FFFFFF';
      const color = '#000000';
      const border = isAdmin ? '1px solid #BAE6FD' : '1px solid #CBD5E1';
      const radius = isAdmin ? '16px 16px 4px 16px' : '16px 16px 16px 4px';
      return `
        <div class="comm-bubble-wrapper ${m.sender}" style="display:flex; flex-direction:column; max-width:70%; align-self:${isAdmin ? 'flex-end' : 'flex-start'}; align-items:${isAdmin ? 'flex-end' : 'flex-start'}; margin-bottom:10px;">
          <div class="comm-bubble" style="background:${bg} !important; color:${color} !important; border:${border} !important; border-radius:${radius}; padding:12px 16px; font-size:13.5px; font-weight:700; line-height:1.5; box-shadow:0 2px 5px rgba(0,0,0,0.08);">
            ${m.text}
          </div>
          <div class="comm-bubble-meta" style="font-size:11px; font-weight:600; color:#475569 !important; margin-top:4px; display:flex; align-items:center; gap:4px;">
            ${isAdmin ? '<i class="ri-check-double-line" style="color:#2563EB;"></i> الدعم الفني • ' : userName + ' • '}
            ${m.time}
          </div>
        </div>
      `;
    }).join('');
  } else {
    messagesHtml = `
      <div class="comm-bubble-wrapper admin" style="display:flex; flex-direction:column; max-width:70%; align-self:flex-end; align-items:flex-end; margin-bottom:10px;">
        <div class="comm-bubble" style="background:#E0F2FE !important; color:#000000 !important; border:1px solid #BAE6FD !important; border-radius:16px 16px 4px 16px; padding:12px 16px; font-size:13.5px; font-weight:700; line-height:1.5; box-shadow:0 2px 5px rgba(0,0,0,0.08);">
          أهلاً بك يا ${userName}! يسعدنا تواصلك معنا، كيف يمكننا مساعدتك اليوم؟
        </div>
        <div class="comm-bubble-meta" style="font-size:11px; font-weight:600; color:#475569 !important; margin-top:4px; display:flex; align-items:center; gap:4px;">
          <i class="ri-check-double-line" style="color:#2563EB;"></i> الدعم الفني • الآن
        </div>
      </div>
    `;
  }

  return `
    <!-- Header -->
    <div class="comm-chat-header" data-active-chat-user="${userId}">
      <div class="comm-chat-user-details">
        <div class="comm-avatar ${isDriver ? 'driver' : ''}">
          ${userName.charAt(0)}
          <div class="comm-avatar-badge"></div>
        </div>
        <div>
          <div style="display:flex;align-items:center;gap:8px;">
            <h4 style="margin:0;font-size:15px;font-weight:700;color:var(--text-primary);">${userName}</h4>
            <span class="badge" style="font-size:11px;background:${isDriver ? '#E0F2FE' : '#F3E8FF'};color:${isDriver ? '#0369A1' : '#7E22CE'};font-weight:700;">
              ${roleText}
            </span>
            ${(userObj?.ratingCount && userObj.ratingCount > 0) ? `
              <span style="font-size:12px;font-weight:800;color:var(--warning);display:flex;align-items:center;gap:3px;" title="التقييمات والرحلات">
                <i class="ri-star-fill"></i> ${ratingVal} (${userObj.ratingCount} تقييم • ${userObj.totalTrips || 0} رحلة)
              </span>
            ` : `
              <span style="font-size:11px;font-weight:600;color:var(--text-light);display:flex;align-items:center;gap:3px;" title="التقييمات والرحلات">
                <i class="ri-star-line"></i> جديد (بدون تقييم • ${userObj?.totalTrips || 0} رحلة)
              </span>
            `}
          </div>
          <div style="font-size:11px;color:var(--text-secondary);margin-top:2px;">
            📱 ${userPhone} • ID: ${userId.substring(0, 8).toUpperCase()}
          </div>
        </div>
      </div>
      <div>
        <button class="btn btn-outline btn-sm" onclick="viewUserProfile('${userId}', '${isDriver ? 'driver' : 'rider'}')">
          <i class="ri-user-line"></i> عرض الملف كامل
        </button>
      </div>
    </div>

    <!-- Messages Container -->
    <div class="comm-chat-messages" id="commChatMessagesContainer">
      ${messagesHtml}
    </div>

    <!-- Input Zone -->
    <div class="comm-chat-input-zone">
      <div class="comm-quick-replies">
        <button class="comm-quick-pill" onclick="sendCommQuickReply('أهلاً بك 🖐️ يسعدنا خدمتك في inRide')">أهلاً بك 🖐️</button>
        <button class="comm-quick-pill" onclick="sendCommQuickReply('تم شحن المحفظة بنجاح ✅ يرجى التحديث')">تم الشحن ✅</button>
        <button class="comm-quick-pill" onclick="sendCommQuickReply('تم استقبال الطلب وجاري المتابعة معك 📋')">جاري المتابعة 📋</button>
        <button class="comm-quick-pill" onclick="sendCommQuickReply('شكراً لتواصلك معنا مع تحيات فريق inRide 🚗')">شكراً لك 🚗</button>
      </div>
      <div class="comm-input-bar">
        <input type="text" id="commChatInput" class="comm-text-input" placeholder="اكتب رسالتك المباشرة هنا..." onkeypress="if(event.key === 'Enter') sendCommChatMessage()">
        <button class="btn btn-primary" onclick="sendCommChatMessage()" style="padding:10px 20px;border-radius:var(--radius-md);display:flex;align-items:center;gap:6px;">
          <span>إرسال</span>
          <i class="ri-send-plane-fill"></i>
        </button>
      </div>
    </div>
  `;
}

function renderCommunication() {
  try {
    // Ensure an active user is pre-selected if available
    if (!commActiveUserId) {
      const contacts = getCommContactsList();
      if (contacts.length > 0) {
        commActiveUserId = contacts[0].id;
        commActiveUserRole = contacts[0].role || 'rider';
      }
    }

    return `
      <div class="page-section">
        <!-- Communication Header -->
        <div class="card" style="margin-bottom:16px;padding:16px;">
          <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
            <div>
              <h3 style="margin:0;font-size:16px;font-weight:800;color:var(--text-primary);display:flex;align-items:center;gap:8px;">
                <i class="ri-chat-smile-2-fill text-blue" style="font-size:20px;"></i> مركز التواصل والمحادثات المباشرة (inRide)
              </h3>
              <p style="margin:4px 0 0 0;font-size:12px;color:var(--text-secondary);">
                إدارة المحادثات المباشرة، التذاكر والشكاوى، ومتابعة محادثات الرحلات بين الركاب والكباتن
              </p>
            </div>
            <div style="display:flex;gap:8px;">
              <button class="btn btn-outline btn-sm" onclick="initCommChatSync(true)">
                <i class="ri-refresh-line"></i> تحديث البيانات
              </button>
            </div>
          </div>
        </div>

        <!-- Navigation Tabs -->
        <div style="display:flex;gap:8px;margin-bottom:16px;background:var(--bg-primary);padding:6px;border-radius:var(--radius-md);">
          <button class="btn btn-sm ${currentCommunicationTab === 'chat' ? 'btn-primary' : 'btn-outline'}" onclick="setCommunicationTab('chat')">
            💬 المحادثات المباشرة والدعم الفني
          </button>
          <button class="btn btn-sm ${currentCommunicationTab === 'tickets' ? 'btn-primary' : 'btn-outline'}" onclick="setCommunicationTab('tickets')">
            🎫 الشكاوى والتذاكر
          </button>
          <button class="btn btn-sm ${currentCommunicationTab === 'ride_chats' ? 'btn-primary' : 'btn-outline'}" onclick="setCommunicationTab('ride_chats')">
            🚗💬 محادثات الرحلات
          </button>
        </div>

        ${currentCommunicationTab === 'chat' ? `
          <div class="comm-chat-layout" style="display:grid;grid-template-columns:360px 1fr;gap:16px;min-height:640px;background:var(--bg-primary,#F8FAFC);border-radius:16px;border:1px solid var(--border-color,#E2E8F0);overflow:hidden;">
            <!-- Left Sidebar: Conversations & Contacts List -->
            <div class="comm-chat-sidebar" style="border-left:1px solid var(--border-color,#E2E8F0);background:white;display:flex;flex-direction:column;max-height:680px;overflow-y:auto;">
              <div class="comm-sidebar-header" style="padding:16px;border-bottom:1px solid var(--border-light);">
                <div class="comm-search-box" style="margin-bottom:10px;">
                  <i class="ri-search-line"></i>
                  <input type="text" placeholder="البحث باسم الكابتن أو الراكب..." value="${commSearchQuery || ''}" oninput="onCommSearchInput(this.value)">
                </div>
                <div class="comm-filter-pills" style="display:flex;gap:4px;">
                  <button class="comm-pill ${commRoleFilter === 'all' ? 'active' : ''}" onclick="setCommRoleFilter('all')">الكل</button>
                  <button class="comm-pill ${commRoleFilter === 'driver' ? 'active' : ''}" onclick="setCommRoleFilter('driver')">الكباتن 🚗</button>
                  <button class="comm-pill ${commRoleFilter === 'rider' ? 'active' : ''}" onclick="setCommRoleFilter('rider')">الركاب 👤</button>
                </div>
              </div>

              <div class="comm-conv-list" id="commConvListContainer" style="flex:1;overflow-y:auto;">
                ${renderCommConversationsListHtml()}
              </div>
            </div>

            <!-- Right Main Chat Box -->
            <div class="comm-chat-main" id="commMainChatPanel" style="background:white;display:flex;flex-direction:column;height:100%;min-height:600px;">
              ${renderCommChatPanelHtml(commActiveUserId)}
            </div>
          </div>
        ` : currentCommunicationTab === 'tickets' ? `
          <!-- Tickets and Complaints View -->
          <div class="card">
            <div class="card-header" style="padding:16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
              <div>
                <h3 style="margin:0;font-size:15px;font-weight:700;"><i class="ri-ticket-2-line text-blue"></i> سجل التذاكر والشكاوى الحقيقي (Supabase DB)</h3>
                <p style="font-size:11px;color:var(--text-secondary);margin:2px 0 0 0;">استقبال الشكاوى والملاحظات المفتوحة من تطبيق العميل ومتابعة حلها</p>
              </div>
              <div style="display:flex;gap:4px;background:var(--bg-primary);padding:4px;border-radius:var(--radius-md);">
                <button class="btn btn-sm ${supportFilterStatus === 'all' ? 'btn-primary' : 'btn-outline'}" onclick="setSupportFilter('all')">الكل</button>
                <button class="btn btn-sm ${supportFilterStatus === 'open' ? 'btn-primary' : 'btn-outline'}" onclick="setSupportFilter('open')">مفتوحة</button>
                <button class="btn btn-sm ${supportFilterStatus === 'pending' ? 'btn-primary' : 'btn-outline'}" onclick="setSupportFilter('pending')">متابعة</button>
                <button class="btn btn-sm ${supportFilterStatus === 'resolved' ? 'btn-primary' : 'btn-outline'}" onclick="setSupportFilter('resolved')">تم الحل</button>
              </div>
            </div>
            <div class="card-body" style="padding:0;overflow-x:auto;">
              <table class="data-table" style="width:100%;font-size:12px;">
                <thead>
                  <tr style="background:var(--bg-primary);">
                    <th style="padding:12px 14px;">المستخدم</th>
                    <th style="padding:12px 14px;">نوع / تفاصيل الشكوى</th>
                    <th style="padding:12px 14px;">تاريخ الورود</th>
                    <th style="padding:12px 14px;">الحالة</th>
                    <th style="padding:12px 14px;text-align:center;">إجراءات التذكرة</th>
                  </tr>
                </thead>
                <tbody>
                  ${(!liveSupportChats || liveSupportChats.length === 0) ? `
                    <tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-light);">لا توجد تذاكر دعم مسجلة في هذا القسم حالياً</td></tr>
                  ` : liveSupportChats.filter(c => supportFilterStatus === 'all' || c.status === supportFilterStatus).map(tkt => {
      const isDriver = tkt.user_type === 'driver';
      const timeStr = tkt.last_message_at ? new Date(tkt.last_message_at).toLocaleString('ar-EG') : 'الآن';
      const statusBg = tkt.status === 'resolved' ? '#D1FAE5' : (tkt.status === 'pending' ? '#FEF3C7' : '#FEE2E2');
      const statusColor = tkt.status === 'resolved' ? '#065F46' : (tkt.status === 'pending' ? '#92400E' : '#991B1B');
      const statusText = tkt.status === 'resolved' ? 'تم الحل ✅' : (tkt.status === 'pending' ? 'قيد المتابعة ⏳' : 'مفتوحة 🔴');

      return `
                      <tr style="border-bottom:1px solid var(--border-light);">
                        <td style="padding:12px 14px;">
                          <div style="font-weight:700;color:var(--text-primary);">${tkt.user_name || (isDriver ? 'كابتن inRide' : 'عميل inRide')}</div>
                          <div style="font-size:11px;color:var(--text-secondary);">${tkt.phone || '—'}</div>
                        </td>
                        <td style="padding:12px 14px;">
                          <div style="font-weight:600;color:var(--text-primary);">${tkt.last_message || 'طلب مساعدة جديدة من التطبيق'}</div>
                          <span class="badge" style="font-size:10px;background:${isDriver ? '#E0F2FE' : '#F3E8FF'};color:${isDriver ? '#0369A1' : '#7E22CE'};">${isDriver ? 'كابتن 🚗' : 'راكب 👤'}</span>
                        </td>
                        <td style="padding:12px 14px;white-space:nowrap;">${timeStr}</td>
                        <td style="padding:12px 14px;">
                          <span class="badge" style="background:${statusBg};color:${statusColor};font-weight:700;padding:4px 10px;border-radius:12px;">${statusText}</span>
                        </td>
                        <td style="padding:12px 14px;text-align:center;">
                          <div style="display:flex;gap:6px;justify-content:center;">
                            <button class="btn btn-sm btn-primary" onclick="openDirectUserChat('${tkt.id || tkt.user_id}', '${tkt.user_name || ''}', '${isDriver ? 'driver' : 'rider'}')">
                              💬 محادثة مباشرة
                            </button>
                            ${tkt.status !== 'resolved' ? `
                              <button class="btn btn-sm btn-outline" style="color:var(--success);border-color:var(--success);font-weight:700;" onclick="resolveSupportTicket('${tkt.id || tkt.user_id}')">
                                ✔️ إغلاق وحل الشكوى
                              </button>
                            ` : ''}
                          </div>
                        </td>
                      </tr>
                    `;
    }).join('')}
                </tbody>
              </table>
            </div>
          </div>
        ` : `
          <!-- Ride Chats View -->
          <div class="card">
            <div class="card-header" style="padding:16px;">
              <h3 style="margin:0;font-size:15px;font-weight:700;"><i class="ri-car-line text-blue"></i> محادثات الرحلات المباشرة بين الركاب والكباتن (Supabase DB)</h3>
              <p style="font-size:11px;color:var(--text-secondary);margin:2px 0 0 0;">متابعة تفاصيل سِجل الرسائل الفورية بين السائق والعميل أثناء الرحلات النشطة والسابقة</p>
            </div>
            <div class="card-body" style="padding:0;">
              <div style="display:grid;grid-template-columns: 360px 1fr;min-height:500px;">
                <div style="border-left:1px solid var(--border-color);overflow-y:auto;max-height:550px;" id="rideChatsListContainer">
                  ${renderRideChatsListHtml()}
                </div>
                <div id="rideChatMainPanel" style="display:flex;flex-direction:column;">
                  <div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--text-light);padding:40px;">
                    <i class="ri-car-line" style="font-size:54px;margin-bottom:12px;color:var(--medium-blue);"></i>
                    <h4 style="margin:0 0 6px 0;">اختر رحلة لمشاهدة سِجل المحادثة</h4>
                    <p style="font-size:12px;margin:0;">يمكنك تتبع كافة الرسائل المتبادلة بين الكابتن والراكب في أي رحلة</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        `}
      </div>
    `;
  } catch (err) {
    console.error('Error rendering communication page:', err);
    return `
      <div class="page-section">
        <div class="card" style="padding:24px;text-align:center;">
          <h3 style="color:var(--error);"><i class="ri-error-warning-line"></i> تعذر تحميل مركز التواصل والمحادثات</h3>
          <p style="font-size:13px;color:var(--text-secondary);">${err.message || err}</p>
          <button class="btn btn-primary" onclick="renderPage('communication')">إعادة المحاولة</button>
        </div>
      </div>
    `;
  }
}

function renderCommConversationsList() {
  const container = document.getElementById('commConvListContainer');
  if (!container) return;
  const newHtml = renderCommConversationsListHtml();
  if (container.innerHTML !== newHtml) {
    container.innerHTML = newHtml;
  }
}

async function initCommChatSync(force = false) {
  try {
    await loadCommUsersFromSupabase();
    await loadSupportChatsFromSupabase();
    renderCommConversationsList();

    if (!commActiveUserId) {
      const contacts = getCommContactsList();
      if (contacts.length > 0) {
        commActiveUserId = contacts[0].id;
        commActiveUserRole = contacts[0].role || 'rider';
      }
    }

    if (commActiveUserId) {
      loadCommMessagesThread(commActiveUserId, force);
    }
    updateCommunicationBadge();

    if (supabaseClient && !window._commRealtimeSubscribed) {
      window._commRealtimeSubscribed = true;
      try {
        supabaseClient
          .channel('admin_comm_realtime_channel')
          .on('postgres_changes', { event: '*', schema: 'public', table: 'support_messages' }, payload => {
            const newMsg = payload.new;
            if (newMsg) {
              const targetId = newMsg.user_id || newMsg.sender_id || newMsg.conversation_id;
              if (targetId && currentPage === 'communication' && commActiveUserId === targetId) {
                loadCommMessagesThread(targetId, false);
              }
              loadSupportChatsFromSupabase().then(() => {
                if (currentPage === 'communication') renderCommConversationsList();
              });
            }
          })
          .on('postgres_changes', { event: '*', schema: 'public', table: 'support_chats' }, () => {
            loadSupportChatsFromSupabase().then(() => {
              if (currentPage === 'communication') renderCommConversationsList();
            });
          })
          .subscribe();
      } catch (_) { }
    }
  } catch (e) {
    console.warn('[Comm] initCommChatSync warning:', e);
  }
}

async function loadCommMessagesThread(userId, isSwitching = false) {
  if (!userId) return;
  const mainPanel = document.getElementById('commMainChatPanel');
  if (!mainPanel) return;

  const currentHeaderEl = mainPanel.querySelector('.comm-chat-header');
  const renderedUserId = currentHeaderEl ? currentHeaderEl.getAttribute('data-active-chat-user') : null;

  // If we are switching users or header is not for this user, render the shell
  if (isSwitching || renderedUserId !== userId) {
    mainPanel.innerHTML = renderCommChatPanelHtml(userId);
    const container = document.getElementById('commChatMessagesContainer');
    if (container) container.scrollTop = container.scrollHeight;
  }

  // Load real messages in background from Supabase
  let userObj = null;
  if (mockData.drivers) userObj = mockData.drivers.find(d => d.uid === userId);
  if (!userObj && mockData.passengers) userObj = mockData.passengers.find(p => p.uid === userId);
  const userName = userObj ? userObj.name : 'مستخدم';

  let messagesList = [
    { sender: 'admin', text: `أهلاً بك يا ${userName}! يسعدنا تواصلك معنا، كيف يمكننا مساعدتك اليوم؟`, time: 'الآن' }
  ];

  if (supabaseClient) {
    try {
      const { data: realMsgs } = await supabaseClient
        .from('support_messages')
        .select('*')
        .or(`sender_id.eq.${userId},receiver_id.eq.${userId},user_id.eq.${userId},conversation_id.eq.${userId}`)
        .order('created_at', { ascending: true });

      if (realMsgs && realMsgs.length > 0) {
        messagesList = realMsgs.map(m => {
          const isAdmin = m.sender_type === 'admin' || m.is_admin === true || m.sender_role === 'admin' || m.sender_id === null || (currentAdminUser && m.sender_id === currentAdminUser.id);
          const t = new Date(m.created_at || Date.now()).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
          return {
            sender: isAdmin ? 'admin' : 'user',
            text: m.message || m.text || '',
            time: t
          };
        });
      }
    } catch (_) { }
  }

  // Save to cache
  commMessagesCache[userId] = messagesList;

  // If still on the same active user, smoothly update the messages box ONLY if changed
  if (commActiveUserId === userId) {
    const container = document.getElementById('commChatMessagesContainer');
    if (container) {
      const messagesHtml = messagesList.map(m => {
        const isAdmin = m.sender === 'admin';
        const bg = isAdmin ? '#E0F2FE' : '#FFFFFF';
        const color = '#000000';
        const border = isAdmin ? '1px solid #BAE6FD' : '1px solid #CBD5E1';
        const radius = isAdmin ? '16px 16px 4px 16px' : '16px 16px 16px 4px';
        return `
          <div class="comm-bubble-wrapper ${m.sender}" style="display:flex; flex-direction:column; max-width:70%; align-self:${isAdmin ? 'flex-end' : 'flex-start'}; align-items:${isAdmin ? 'flex-end' : 'flex-start'}; margin-bottom:10px;">
            <div class="comm-bubble" style="background:${bg} !important; color:${color} !important; border:${border} !important; border-radius:${radius}; padding:12px 16px; font-size:13.5px; font-weight:700; line-height:1.5; box-shadow:0 2px 5px rgba(0,0,0,0.08);">
              ${m.text}
            </div>
            <div class="comm-bubble-meta" style="font-size:11px; font-weight:600; color:#475569 !important; margin-top:4px; display:flex; align-items:center; gap:4px;">
              ${isAdmin ? '<i class="ri-check-double-line" style="color:#2563EB;"></i> الدعم الفني • ' : userName + ' • '}
              ${m.time}
            </div>
          </div>
        `;
      }).join('');

      if (container.innerHTML !== messagesHtml) {
        container.innerHTML = messagesHtml;
        container.scrollTop = container.scrollHeight;
      }
    }
  }
}

function generateUUID() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

async function sendCommChatMessage() {
  const input = document.getElementById('commChatInput');
  if (!input || !input.value.trim() || !commActiveUserId) return;

  const msgText = input.value.trim();
  input.value = '';

  const container = document.getElementById('commChatMessagesContainer');
  const nowStr = new Date().toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

  if (container) {
    const bubble = document.createElement('div');
    bubble.className = 'comm-bubble-wrapper admin';
    bubble.style.cssText = 'display:flex; flex-direction:column; max-width:70%; align-self:flex-end; align-items:flex-end; margin-bottom:10px;';
    bubble.innerHTML = `
      <div class="comm-bubble" style="background:#E0F2FE !important; color:#000000 !important; border:1px solid #BAE6FD !important; border-radius:16px 16px 4px 16px; padding:12px 16px; font-size:13.5px; font-weight:700; line-height:1.5; box-shadow:0 2px 5px rgba(0,0,0,0.08);">${msgText}</div>
      <div class="comm-bubble-meta" style="font-size:11px; font-weight:600; color:#475569 !important; margin-top:4px; display:flex; align-items:center; gap:4px;"><i class="ri-check-double-line" style="color:#2563EB;"></i> الدعم الفني • ${nowStr}</div>
    `;
    container.appendChild(bubble);
    container.scrollTop = container.scrollHeight;
  }

  // Find user details
  let userObj = null;
  if (mockData.drivers) userObj = mockData.drivers.find(d => d.uid === commActiveUserId);
  if (!userObj && mockData.passengers) userObj = mockData.passengers.find(p => p.uid === commActiveUserId);
  const userName = userObj ? userObj.name : 'عميل inRide';

  // Send to Supabase if connected
  if (supabaseClient) {
    try {
      const msgId = generateUUID();
      const adminUuid = (currentAdminUser && currentAdminUser.id && currentAdminUser.id.length > 20)
        ? currentAdminUser.id
        : '00000000-0000-0000-0000-000000000000';

      // 1. Re-open ticket in support_chats table so status is open and app client syncs immediately
      try {
        await supabaseClient.from('support_chats').upsert({
          id: commActiveUserId,
          user_id: commActiveUserId,
          user_name: userName,
          user_type: commActiveUserRole === 'driver' ? 'driver' : 'rider',
          last_message: msgText,
          last_message_at: new Date().toISOString(),
          status: 'open',
          updated_at: new Date().toISOString()
        });
      } catch (chatErr) {
        console.warn('[Comm] Upsert support_chats warning:', chatErr);
      }

      // 2. Insert message into support_messages
      try {
        const { error: insertErr } = await supabaseClient.from('support_messages').insert({
          id: msgId,
          conversation_id: commActiveUserId,
          user_id: commActiveUserId,
          sender_id: adminUuid,
          receiver_id: commActiveUserId,
          sender_type: 'admin',
          sender_role: 'admin',
          sender_name: 'inRide',
          message: msgText,
          text: msgText,
          is_admin: true,
          status: 'delivered',
          created_at: new Date().toISOString()
        });

        if (insertErr) {
          console.warn('[Comm] Retrying simplified insert into support_messages:', insertErr);
          await supabaseClient.from('support_messages').insert({
            id: msgId,
            conversation_id: commActiveUserId,
            user_id: commActiveUserId,
            sender_type: 'admin',
            message: msgText,
            text: msgText,
            is_admin: true,
            status: 'delivered',
            created_at: new Date().toISOString()
          });
        }
      } catch (msgErr) {
        console.warn('[Comm] Error inserting support_messages:', msgErr);
      }

      // 3. Send notification trigger & OS Push
      try {
        await supabaseClient.from('notifications').insert({
          id: generateUUID(),
          user_id: commActiveUserId,
          title: 'inRide',
          body: msgText,
          type: 'support_chat',
          created_at: new Date().toISOString()
        });
        await dispatchPushNotificationToUser(commActiveUserId, "رسالة جديدة من إدارة inRide", msgText, msgId);
      } catch (notifErr) {
        console.warn('[Comm] Insert notification/push warning:', notifErr);
      }
    } catch (err) {
      console.error('[Comm] Critical error in sendCommChatMessage:', err);
    }
  }

  showToast('✅ تم إرسال الرسالة بنجاح');
}

function sendCommQuickReply(text) {
  const input = document.getElementById('commChatInput');
  if (input) {
    input.value = text;
    sendCommChatMessage();
  }
}


function renderWallet() {
  if (!financialState.isLoaded) {
    loadFinancialDataFromSupabase().then(() => {
      const container = document.getElementById('pageContent');
      if (container && currentPage === 'wallet') {
        container.innerHTML = renderWalletContentHtml();
      }
    });
  }
  return renderWalletContentHtml();
}


function setFinancialTxStatusFilter(filter) {
  financialState.txStatusFilter = filter;
  renderPage('wallet');
}

function renderWalletContentHtml() {
  const filteredTx = getFilteredTransactions();
  const pendingRequests = (financialState.rechargeRequests || []).filter(r => r.status === 'pending');
  const pendingTx = (financialState.transactions || []).filter(t => t.type === 'charge_pending');
  const pendingRechargeList = [
    ...pendingRequests.map(r => ({
      id: r.id,
      user_id: r.user_id,
      amount: r.amount,
      payment_method: r.payment_method || 'InstaPay',
      receipt_url: r.receipt_url,
      created_at: r.created_at,
      is_recharge_request: true,
      user_name: r.user_name,
      user_phone: r.user_phone,
      user_type: r.user_type
    })),
    ...pendingTx.filter(t => !pendingRequests.some(r => r.user_id === t.user_id && Math.abs(r.amount - t.amount) < 0.1)).map(t => ({
      id: t.id,
      user_id: t.user_id,
      amount: t.amount,
      payment_method: t.payment_method || 'InstaPay',
      receipt_url: t.receipt_url,
      created_at: t.created_at,
      is_recharge_request: false
    }))
  ];

  // Update sidebar badge if exists
  const badgeEl = document.getElementById('pendingRechargeBadge');
  if (badgeEl) {
    badgeEl.textContent = pendingRechargeList.length;
    badgeEl.style.display = pendingRechargeList.length > 0 ? 'inline-block' : 'none';
  }

  // Active (unsettled) transactions for current period statistics
  const activeTx = filteredTx.filter(t => !t.is_settled);

  let totalIncome = 0;
  let totalExpense = 0;

  activeTx.forEach(t => {
    const amt = parseFloat(t.amount || 0);
    if (amt > 0) totalIncome += amt;
    else totalExpense += Math.abs(amt);
  });

  const netBalance = totalIncome - totalExpense;
  const activeMethods = financialState.paymentMethods || [];

  // Table filter for transactions ledger
  const txFilter = financialState.txStatusFilter || 'all';
  let displayTx = filteredTx;
  if (txFilter === 'active') displayTx = filteredTx.filter(t => !t.is_settled);
  else if (txFilter === 'settled') displayTx = filteredTx.filter(t => t.is_settled);

  return `
    <div class="page-section">
      <!-- Financial Top Action Toolbar -->
      <div class="card" style="margin-bottom:20px;padding:16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
          <div style="display:flex;gap:8px;flex-wrap:wrap;">
            <button class="btn btn-primary" onclick="openFinancialModal('rechargeModal')">
              <i class="ri-add-circle-line"></i> شحن رصيد مستخدم (رفع ريسيت)
            </button>
            <button class="btn btn-outline" style="border-color:var(--error);color:var(--error);" onclick="openFinancialModal('payoutModal')">
              <i class="ri-arrow-up-circle-line"></i> سحب وتسوية مستحقات سائق
            </button>
            <button class="btn btn-outline" onclick="openFinancialModal('paymentMethodsModal')">
              <i class="ri-bank-card-line"></i> إدارة طرق الدفع المقبولة
            </button>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;">
            <button class="btn btn-outline" style="border-color:var(--warning);color:#D97706;" onclick="openFinancialModal('resetPeriodModal')">
              <i class="ri-restart-line"></i> تصفير وتصفية الأرقام
            </button>
            <button class="btn btn-primary" style="background:#059669;" onclick="generateFinancialReport()">
              <i class="ri-printer-line"></i> إصدار تقرير مالي احترافي (PDF)
            </button>
          </div>
        </div>
      </div>

      <!-- Financial Period Filter Tabs -->
      <div class="card" style="margin-bottom:24px;padding:14px;">
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;">
          <div style="font-weight:700;font-size:14px;color:var(--text-primary);">
            <i class="ri-calendar-event-line text-blue"></i> النطاق الزمني للحسابات والإحصائيات:
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;">
            <button class="btn btn-sm ${financialState.selectedPeriod === 'today' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialPeriodFilter('today')">📅 اليوم</button>
            <button class="btn btn-sm ${financialState.selectedPeriod === 'week' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialPeriodFilter('week')">🗓️ هذا الأسبوع</button>
            <button class="btn btn-sm ${financialState.selectedPeriod === 'month' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialPeriodFilter('month')">📊 هذا الشهر</button>
            <button class="btn btn-sm ${financialState.selectedPeriod === 'year' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialPeriodFilter('year')">📈 هذه السنة</button>
            <button class="btn btn-sm ${financialState.selectedPeriod === 'all' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialPeriodFilter('all')">🌐 كل الفترات</button>
          </div>
        </div>
      </div>

      <!-- Financial Stats Grid -->
      <div class="stats-grid" style="grid-template-columns: repeat(4, 1fr); margin-bottom: 24px;">
        <div class="stat-card blue">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-wallet-3-fill"></i></div>
          </div>
          <div class="stat-card-value">${netBalance.toLocaleString()}</div>
          <div class="stat-card-label">صافي رصيد الفترة النشط (ج.م)</div>
        </div>
        <div class="stat-card green">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-arrow-down-circle-fill"></i></div>
          </div>
          <div class="stat-card-value">${totalIncome.toLocaleString()}</div>
          <div class="stat-card-label">إجمالي التحويلات والإيرادات (ج.م)</div>
        </div>
        <div class="stat-card red">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-arrow-up-circle-fill"></i></div>
          </div>
          <div class="stat-card-value">${totalExpense.toLocaleString()}</div>
          <div class="stat-card-label">إجمالي المسحوبات والمصروفات (ج.م)</div>
        </div>
        <div class="stat-card yellow">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-shield-check-fill"></i></div>
          </div>
          <div class="stat-card-value">${filteredTx.filter(t => t.is_settled).length}</div>
          <div class="stat-card-label">المعاملات المصفاة والمؤرشفة</div>
        </div>
      </div>

      <!-- Dedicated Pending Top-up Requests Section -->
      <div class="card" style="margin-bottom:24px;border:2px solid #F59E0B;box-shadow:0 4px 14px rgba(245,158,11,0.18);">
        <div class="card-header" style="display:flex;justify-content:space-between;align-items:center;background:#FEF3C7;padding:14px 18px;border-bottom:1px solid #FDE68A;">
          <div style="display:flex;align-items:center;gap:10px;">
            <i class="ri-time-line" style="font-size:24px;color:#D97706;"></i>
            <div>
              <h3 style="color:#92400E;margin:0;font-size:15px;font-weight:800;">طلبات الشحن المعلقة (مراجعة إيصالات التحويل) 📥</h3>
              <p style="color:#B45309;margin:0;font-size:11px;margin-top:2px;">مراجعة وقبول/رفض طلبات شحن المحفظة عبر InstaPay المرفقة من العملاء والكبائن</p>
            </div>
          </div>
          <span class="badge" style="background:#D97706;color:white;font-size:12px;padding:6px 14px;border-radius:20px;font-weight:700;">
            ${pendingRechargeList.length} طلبات معلقة
          </span>
        </div>
        <div class="card-body" style="padding:0;overflow-x:auto;">
          <table class="data-table" style="width:100%;font-size:12px;">
            <thead>
              <tr style="background:#FFFBEB;color:#78350F;border-bottom:2px solid #FDE68A;">
                <th style="padding:10px 14px;">تاريخ الطلب</th>
                <th style="padding:10px 14px;">بيانات الراكب / الكابتن</th>
                <th style="padding:10px 14px;">طريقة التحويل</th>
                <th style="padding:10px 14px;">المبلغ المطلوب</th>
                <th style="padding:10px 14px;">إيصال التحويل (صورة)</th>
                <th style="padding:10px 14px;text-align:center;">إجراء الإدارة</th>
              </tr>
            </thead>
            <tbody>
              ${pendingRechargeList.length === 0 ?
      `<tr><td colspan="6" style="text-align:center;padding:32px;color:var(--text-light);font-size:12.5px;">✨ لا توجد طلبات شحن معلقة حالياً. جميع إيصالات التحويل تم مراجعتها بالكامل!</td></tr>` :
      pendingRechargeList.map(tx => {
        const amt = parseFloat(tx.amount || 0);
        const dateStr = new Date(tx.created_at || Date.now()).toLocaleString('ar-EG');
        const userObj = (financialState.usersList || []).find(u => u.id === tx.user_id) || { name: 'مستخدم inRide', phone: '', role: 'راكب' };
        const userRoleBadge = userObj.role === 'driver' ? 'كابتن 🚗' : 'راكب 👤';
        const receiptUrl = tx.receipt_url || '';

        return `
                    <tr style="border-bottom:1px solid #FEF3C7;background:white;">
                      <td style="white-space:nowrap;padding:12px 14px;font-weight:600;">${dateStr}</td>
                      <td style="padding:12px 14px;">
                        <div style="font-weight:800;color:var(--text-primary);">${userObj.name}</div>
                        <div style="font-size:11px;color:var(--text-secondary);display:flex;align-items:center;gap:6px;margin-top:2px;">
                          <span>📱 ${userObj.phone || 'بدون هاتف'}</span>
                          <span class="badge" style="background:#EBF8FF;color:#2B6CB0;font-size:9.5px;padding:1px 6px;">${userRoleBadge}</span>
                        </div>
                      </td>
                      <td style="padding:12px 14px;">
                        <span class="badge" style="background:#F3E8FF;color:#6B21A8;padding:4px 10px;border-radius:8px;font-weight:700;font-size:11px;">
                          💳 ${tx.payment_method || 'InstaPay'}
                        </span>
                      </td>
                      <td style="padding:12px 14px;font-weight:900;color:#059669;font-size:14px;white-space:nowrap;">
                        +${amt.toLocaleString()} ج.م
                      </td>
                      <td style="padding:12px 14px;">
                        ${receiptUrl ?
            `<button class="btn btn-sm btn-outline" style="background:#EFF6FF;border-color:#3B82F6;color:#1D4ED8;font-weight:700;padding:5px 12px;border-radius:8px;" onclick="viewReceiptModal('${receiptUrl}', 'إيصال شحن معلق', '${userObj.name}', ${amt}, '${dateStr}', '${tx.payment_method || 'InstaPay'}')">
                             📸 معاينة الإيصال
                           </button>` :
            `<span style="color:var(--error);font-weight:bold;font-size:11px;">❌ بدون صورة إيصال</span>`
          }
                      </td>
                      <td style="padding:12px 14px;text-align:center;">
                        <div style="display:flex;gap:8px;justify-content:center;">
                          <button class="btn btn-sm btn-primary" style="background:#059669;border-color:#059669;font-weight:700;padding:6px 14px;border-radius:8px;" onclick="approvePendingRecharge('${tx.id}', '${tx.user_id}', ${amt})">
                            <i class="ri-check-line"></i> قبول وشحن الرصيد
                          </button>
                          <button class="btn btn-sm btn-outline" style="border-color:#DC2626;color:#DC2626;font-weight:700;padding:6px 14px;border-radius:8px;" onclick="rejectPendingRecharge('${tx.id}', '${tx.user_id}')">
                            <i class="ri-close-line"></i> رفض
                          </button>
                        </div>
                      </td>
                    </tr>
                  `;
      }).join('')
    }
            </tbody>
          </table>
        </div>
      </div>

      <div class="grid-2" style="margin-bottom:24px;">
        <!-- Dynamic Payment Methods Section -->
        <div class="card">
          <div class="card-header" style="display:flex;justify-content:space-between;align-items:center;">
            <h3><i class="ri-bank-card-fill text-blue" style="margin-left:8px;"></i> طرق الدفع المقبولة المكتملة (تزامن مع التطبيق)</h3>
            <button class="btn btn-sm btn-outline" onclick="openFinancialModal('paymentMethodsModal')">+ إضافة / تعديل</button>
          </div>
          <div class="card-body">
            <div style="display:flex;flex-direction:column;gap:10px;">
              ${activeMethods.length === 0 ? `<div style="text-align:center;padding:16px;color:var(--text-light);">لا توجد طرق دفع معرفة بعد</div>` :
      activeMethods.map(pm => `
                  <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 14px;background:var(--bg-primary);border-radius:var(--radius-md);border:1px solid var(--border-color);">
                    <div style="display:flex;align-items:center;gap:12px;">
                      <i class="${pm.icon_name || 'ri-bank-card-line'}" style="font-size:22px;color:var(--medium-blue);"></i>
                      <div>
                        <div style="font-weight:700;font-size:13px;color:var(--text-primary);">${pm.name}</div>
                        <div style="font-size:11px;color:var(--text-light);">${pm.account_details || pm.code}</div>
                      </div>
                    </div>
                    <div style="display:flex;align-items:center;gap:8px;">
                      <span class="badge ${pm.is_active ? 'badge-settled' : 'badge-active'}" style="font-size:10px;padding:3px 8px;border-radius:10px;background:${pm.is_active ? '#D1FAE5' : '#F3F4F6'};color:${pm.is_active ? '#065F46' : '#6B7280'};">
                        ${pm.is_active ? 'مفعلة بالتطبيق' : 'معطلة'}
                      </span>
                      <button class="btn btn-sm btn-outline" style="padding:2px 8px;font-size:10px;" onclick="togglePaymentMethodActive('${pm.id}', ${pm.is_active})">
                        ${pm.is_active ? 'تعطيل' : 'تفعيل'}
                      </button>
                      <button class="btn btn-sm btn-outline" style="padding:2px 8px;font-size:10px;color:var(--error);border-color:var(--error);" onclick="deletePaymentMethod('${pm.id}')">
                        حذف
                      </button>
                    </div>
                  </div>
                `).join('')
    }
            </div>
          </div>
        </div>

        <!-- Period Reset & Summary Panel -->
        <div class="card">
          <div class="card-header">
            <h3><i class="ri-history-line text-blue" style="margin-left:8px;"></i> أرشيف وسجل تصفير الفترات المالية</h3>
          </div>
          <div class="card-body" style="max-height:260px;overflow-y:auto;">
            ${(financialState.settlements || []).length === 0 ?
      `<div style="text-align:center;padding:24px;color:var(--text-light);font-size:12px;">لم يتم إجراء أي تصفية أو تصفير للفترات حتى الآن. جميع الحسابات تاريخية ومسجلة بالكامل.</div>` :
      (financialState.settlements || []).map(st => `
                <div style="padding:10px 12px;border-bottom:1px solid var(--border-light);display:flex;justify-content:space-between;align-items:center;">
                  <div>
                    <div style="font-weight:700;font-size:12px;">تصفية فترة: ${st.period_type}</div>
                    <div style="font-size:10px;color:var(--text-light);">${new Date(st.created_at).toLocaleString('ar-EG')} • بواسطة ${st.settled_by || 'المدير'}</div>
                  </div>
                  <div style="text-align:left;">
                    <div style="font-weight:700;font-size:12px;color:var(--medium-blue);">${parseFloat(st.net_balance || 0).toLocaleString()} ج.م</div>
                    <div style="font-size:10px;color:var(--success);">مصفاة وموثقة بالأرشيف</div>
                  </div>
                </div>
              `).join('')
    }
          </div>
        </div>
      </div>

      <!-- Financial Ledger / Transactions History Table -->
      <div class="card">
        <div class="card-header" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
          <div>
            <h3 style="margin:0;"><i class="ri-exchange-funds-fill text-blue" style="margin-left:8px;"></i> سجل المعاملات المالية المكتمل والريسيتات المرفقة</h3>
            <span class="text-light" style="font-size:11px;">عرض وتتبع كافة السجلات المالية والعمليات المصفاة</span>
          </div>
          <div style="display:flex;gap:6px;align-items:center;">
            <button class="btn btn-sm ${txFilter === 'all' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialTxStatusFilter('all')">الكل (${filteredTx.length})</button>
            <button class="btn btn-sm ${txFilter === 'active' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialTxStatusFilter('active')">النشطة والجارية (${filteredTx.filter(t => !t.is_settled).length})</button>
            <button class="btn btn-sm ${txFilter === 'settled' ? 'btn-primary' : 'btn-outline'}" onclick="setFinancialTxStatusFilter('settled')">الأرشيف والمصفاة (${filteredTx.filter(t => t.is_settled).length})</button>
          </div>
        </div>
        <div class="card-body" style="padding:0;overflow-x:auto;">
          <table class="data-table" style="width:100%;font-size:12px;">
            <thead>
              <tr style="background:var(--bg-primary);">
                <th>التاريخ والوقت</th>
                <th>تفاصيل العملية</th>
                <th>طريقة الدفع والمرجع</th>
                <th>صورة الريسيت والإثبات</th>
                <th>المبلغ</th>
                <th>الرصيد بعد</th>
                <th>حالة التصفية والأرشيف</th>
              </tr>
            </thead>
            <tbody>
              ${displayTx.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-light);">لا توجد معاملات مالية مطابقة للفترات المحددة</td></tr>` :
      displayTx.map(tx => {
        const amt = parseFloat(tx.amount || 0);
        const isInc = amt > 0;
        const dateStr = new Date(tx.created_at || Date.now()).toLocaleString('ar-EG');
        const userObj = (financialState.usersList || []).find(u => u.id === tx.user_id) || { name: 'مستخدم', phone: '' };

        return `
                    <tr>
                      <td style="white-space:nowrap;">${dateStr}</td>
                      <td>
                        <div style="font-weight:700;color:var(--text-primary);">${tx.title || 'معاملة مالية'}</div>
                        <div style="font-size:10px;color:var(--text-light);">${userObj.name || ''} ${userObj.phone ? `(${userObj.phone})` : ''}</div>
                      </td>
                      <td>
                        <span class="badge" style="background:#EBF8FF;color:#2B6CB0;padding:2px 6px;border-radius:6px;font-size:10px;">
                          ${tx.payment_method || 'عادي'}
                        </span>
                        ${tx.reference_code ? `<div style="font-size:10px;color:var(--text-light);margin-top:2px;">مرجع: ${tx.reference_code}</div>` : ''}
                      </td>
                      <td>
                        ${tx.receipt_url ?
            `<button class="btn btn-sm btn-outline" style="padding:2px 8px;font-size:10px;" onclick="viewReceiptModal('${tx.receipt_url}', '${tx.reference_code || 'إيصال تحويل'}', '${userObj.name}', ${amt}, '${dateStr}', '${tx.payment_method || ''}')">
                             📷 معاينة الريسيت
                           </button>` :
            `<span style="color:var(--text-light);font-size:10px;">بدون ريسيت</span>`
          }
                      </td>
                      <td style="font-weight:700;color:${isInc ? 'var(--success)' : 'var(--error)'};white-space:nowrap;">
                        ${isInc ? '+' : ''}${amt.toLocaleString()} ج.م
                      </td>
                      <td style="font-weight:600;white-space:nowrap;">
                        ${parseFloat(tx.balance_after || 0).toLocaleString()} ج.م
                      </td>
                      <td>
                        <span class="badge" style="padding:3px 9px;border-radius:10px;font-size:10px;background:${tx.is_settled ? '#E0E7FF' : '#D1FAE5'};color:${tx.is_settled ? '#3730A3' : '#065F46'};font-weight:700;">
                          ${tx.is_settled ? 'مصفاة وموثقة بالأرشيف' : 'نشطة/جارية'}
                        </span>
                      </td>
                    </tr>
                  `;
      }).join('')
    }
            </tbody>
          </table>
        </div>
      </div>
  `;
}

// ---- FINANCIAL ACTIONS & MODALS ----

function openFinancialModal(modalId) {
  let modalEl = document.getElementById(modalId);
  if (!modalEl) {
    modalEl = document.createElement('div');
    modalEl.id = modalId;
    modalEl.className = 'modal-backdrop';
    document.body.appendChild(modalEl);
  }

  const users = financialState.usersList || [];
  const pms = financialState.paymentMethods || [];

  if (modalId === 'rechargeModal') {
    modalEl.innerHTML = `
      <div class="modal-content" style="max-width:500px;width:90%;border-radius:12px;padding:24px;background:white;">
        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #E5E7EB;padding-bottom:12px;margin-bottom:16px;">
          <h3 style="margin:0;font-size:16px;color:var(--text-primary);">💳 شحن رصيد مستخدم (مع رفع الريسيت)</h3>
          <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('rechargeModal')">✕</button>
        </div>
        <form onsubmit="handleRechargeFormSubmit(event)">
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">اختر المستخدم / السائق:</label>
            <select id="rechargeUserSelect" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;">
              <option value="">-- اختر من القائمة --</option>
              ${users.map(u => `<option value="${u.id}">${u.name || 'بدون اسم'} (${u.phone || ''}) - ${u.role === 'driver' ? 'سائق' : 'راكب'} [رصيده الحالي: ${u.wallet_balance || 0} ج.م]</option>`).join('')}
            </select>
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">المبلغ للشحن (ج.م):</label>
            <input type="number" step="0.01" id="rechargeAmountInput" placeholder="مثال: 250" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">طريقة الدفع:</label>
            <select id="rechargeMethodSelect" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;">
              ${pms.map(p => `<option value="${p.code}">${p.name} (${p.account_details || ''})</option>`).join('')}
            </select>
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">رقم مرجع التحويل / المعاملة:</label>
            <input type="text" id="rechargeRefInput" placeholder="مثال: TXN-984210" style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">رفع صورة الريسيت / إيصال التحويل:</label>
            <input type="file" id="rechargeReceiptInput" accept="image/*" style="width:100%;padding:6px;border:1px solid var(--border-color);border-radius:6px;font-size:11px;" />
          </div>
          <div style="margin-bottom:16px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">ملاحظات الإدارة:</label>
            <input type="text" id="rechargeNotesInput" placeholder="أي ملاحظات إضافية..." style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="display:flex;justify-content:flex-end;gap:8px;">
            <button type="button" class="btn btn-outline" onclick="closeFinancialModal('rechargeModal')">إلغاء</button>
            <button type="submit" class="btn btn-primary">تأكيد شحن الرصيد والريسيت</button>
          </div>
        </form>
      </div>
    `;
  } else if (modalId === 'payoutModal') {
    modalEl.innerHTML = `
      <div class="modal-content" style="max-width:500px;width:90%;border-radius:12px;padding:24px;background:white;">
        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #E5E7EB;padding-bottom:12px;margin-bottom:16px;">
          <h3 style="margin:0;font-size:16px;color:var(--error);">💸 سحب وتسوية مستحقات سائق</h3>
          <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('payoutModal')">✕</button>
        </div>
        <form onsubmit="handlePayoutFormSubmit(event)">
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">اختر السائق:</label>
            <select id="payoutUserSelect" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;">
              <option value="">-- اختر السائق --</option>
              ${users.filter(u => u.role === 'driver').map(u => `<option value="${u.id}">${u.name || 'سائق'} (${u.phone || ''}) [رصيده: ${u.wallet_balance || 0} ج.م]</option>`).join('')}
            </select>
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">المبلغ المسحوب / المحول للسائق (ج.م):</label>
            <input type="number" step="0.01" id="payoutAmountInput" placeholder="مثال: 500" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">طريقة التحويل السريع:</label>
            <select id="payoutMethodSelect" required style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;">
              ${pms.map(p => `<option value="${p.code}">${p.name}</option>`).join('')}
            </select>
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">رقم مرجع التحويل المالي:</label>
            <input type="text" id="payoutRefInput" placeholder="مثال: PAYOUT-77182" style="width:100%;padding:10px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:12px;font-weight:700;display:block;margin-bottom:4px;">رفع إثبات ورقة التحويل (الريسيت):</label>
            <input type="file" id="payoutReceiptInput" accept="image/*" style="width:100%;padding:6px;border:1px solid var(--border-color);border-radius:6px;font-size:11px;" />
          </div>
          <div style="display:flex;justify-content:flex-end;gap:8px;">
            <button type="button" class="btn btn-outline" onclick="closeFinancialModal('payoutModal')">إلغاء</button>
            <button type="submit" class="btn btn-primary" style="background:var(--error);border-color:var(--error);">خصم وتسوية المسحوبات</button>
          </div>
        </form>
      </div>
    `;
  } else if (modalId === 'paymentMethodsModal') {
    modalEl.innerHTML = `
      <div class="modal-content" style="max-width:550px;width:90%;border-radius:12px;padding:24px;background:white;">
        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #E5E7EB;padding-bottom:12px;margin-bottom:16px;">
          <h3 style="margin:0;font-size:16px;">⚙️ إدارة طرق الدفع الديناميكية</h3>
          <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('paymentMethodsModal')">✕</button>
        </div>
        <form onsubmit="handleSavePaymentMethodSubmit(event)">
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;">
            <div>
              <label style="font-size:11px;font-weight:700;display:block;margin-bottom:4px;">اسم طريقة الدفع:</label>
              <input type="text" id="pmNameInput" placeholder="مثال: محفظة اتصالات كاش" required style="width:100%;padding:8px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;display:block;margin-bottom:4px;">رمز التعريف (Code):</label>
              <input type="text" id="pmCodeInput" placeholder="مثال: etisalat_cash" required style="width:100%;padding:8px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
            </div>
          </div>
          <div style="margin-bottom:12px;">
            <label style="font-size:11px;font-weight:700;display:block;margin-bottom:4px;">رقم الحساب / المحفظة / IBAN (يظهر للعميل):</label>
            <input type="text" id="pmAccountInput" placeholder="مثال: 01100000000" style="width:100%;padding:8px;border:1px solid var(--border-color);border-radius:6px;font-size:12px;" />
          </div>
          <div style="display:flex;justify-content:flex-end;margin-bottom:16px;">
            <button type="submit" class="btn btn-primary btn-sm">+ إضافة طريقة الدفع للسيستم والتطبيق</button>
          </div>
        </form>
      </div>
    `;
  } else if (modalId === 'resetPeriodModal') {
    modalEl.innerHTML = `
      <div class="modal-content" style="max-width:480px;width:90%;border-radius:12px;padding:24px;background:white;">
        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #E5E7EB;padding-bottom:12px;margin-bottom:16px;">
          <h3 style="margin:0;font-size:16px;color:#D97706;">🔄 تصفير الأرقام وتصفية الحسابات المالية</h3>
          <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('resetPeriodModal')">✕</button>
        </div>
        <div style="font-size:12px;color:var(--text-secondary);margin-bottom:16px;line-height:1.6;">
          ملاحظة هامة: عملية التصفير تقوم بإغلاق وتأكيد حسابات الفترة المختارة وحصر المصاريف، مع <strong>الحفاظ الكامل على السجل التاريخي</strong> للمعاملات في التقارير وقاعدة البيانات بدون حذف.
        </div>
        <div style="display:flex;flex-direction:column;gap:10px;">
          <button class="btn btn-outline" style="padding:12px;text-align:right;" onclick="confirmAndResetPeriod('اليوم')">
            <strong>📅 تصفير وإغلاق حسابات اليوم</strong>
            <div style="font-size:11px;color:var(--text-light);">حصر مصروفات وإيرادات اليوم وتصفير العداد لليوم الجديد</div>
          </button>
          <button class="btn btn-outline" style="padding:12px;text-align:right;" onclick="confirmAndResetPeriod('الأسبوع')">
            <strong>🗓️ تصفير وإغلاق حسابات الأسبوع</strong>
            <div style="font-size:11px;color:var(--text-light);">تصفية حسابات الأسبوع المالي بالكامل</div>
          </button>
          <button class="btn btn-outline" style="padding:12px;text-align:right;" onclick="confirmAndResetPeriod('الشهر')">
            <strong>📊 تصفير وإغلاق حسابات الشهر</strong>
            <div style="font-size:11px;color:var(--text-light);">تصفية واعتماد ميزانية الشهر الحالي</div>
          </button>
        </div>
        <div style="margin-top:16px;text-align:left;">
          <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('resetPeriodModal')">إلغاء</button>
        </div>
      </div>
    `;
  }

  modalEl.style.display = 'flex';
}

function closeFinancialModal(modalId) {
  const modalEl = document.getElementById(modalId);
  if (modalEl) modalEl.style.display = 'none';
}

async function handleRechargeFormSubmit(event) {
  if (event) event.preventDefault();
  const userId = document.getElementById('rechargeUserSelect').value;
  const amount = document.getElementById('rechargeAmountInput').value;
  const method = document.getElementById('rechargeMethodSelect').value;
  const refCode = document.getElementById('rechargeRefInput').value;
  const notes = document.getElementById('rechargeNotesInput').value;
  const fileInput = document.getElementById('rechargeReceiptInput');

  let receiptBase64 = null;
  if (fileInput && fileInput.files && fileInput.files[0]) {
    receiptBase64 = await readFileAsBase64(fileInput.files[0]);
  }

  processTopupWithReceipt(userId, amount, method, refCode, receiptBase64, notes);
}

async function handlePayoutFormSubmit(event) {
  if (event) event.preventDefault();
  const userId = document.getElementById('payoutUserSelect').value;
  const amount = document.getElementById('payoutAmountInput').value;
  const method = document.getElementById('payoutMethodSelect').value;
  const refCode = document.getElementById('payoutRefInput').value;
  const fileInput = document.getElementById('payoutReceiptInput');

  let receiptBase64 = null;
  if (fileInput && fileInput.files && fileInput.files[0]) {
    receiptBase64 = await readFileAsBase64(fileInput.files[0]);
  }

  processDriverPayout(userId, amount, method, refCode, receiptBase64, 'سحب وتصفية مستحقات');
}

async function handleSavePaymentMethodSubmit(event) {
  if (event) event.preventDefault();
  const name = document.getElementById('pmNameInput').value;
  const code = document.getElementById('pmCodeInput').value;
  const account = document.getElementById('pmAccountInput').value;

  addOrUpdatePaymentMethod(null, name, code, account, 'ri-bank-card-line');
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = error => reject(error);
    reader.readAsDataURL(file);
  });
}

function confirmAndResetPeriod(periodName) {
  if (confirm(`هل أنت تأكد من تصفير وإغلاق حسابات (${periodName})؟ سيتم حفظ التقرير في الأرشيف وتصفية أرقام الفترة.`)) {
    closeFinancialModal('resetPeriodModal');
    executePeriodReset(periodName);
  }
}

async function executePeriodReset(periodType) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client) return;

  const filteredTx = getFilteredTransactions();
  const unsettleTx = filteredTx.filter(t => !t.is_settled);

  if (unsettleTx.length === 0) {
    showToast('ℹ️ لا توجد معاملات نشطة في هذه الفترة لتصفيتها. جميع الحسابات مصفاة أو تاريخية بالفعل.');
    return;
  }

  let totalIncome = 0;
  let totalPayouts = 0;

  unsettleTx.forEach(tx => {
    const amt = parseFloat(tx.amount || 0);
    if (amt > 0) totalIncome += amt;
    else totalPayouts += Math.abs(amt);
  });

  const netBalance = totalIncome - totalPayouts;
  const nowStr = new Date().toISOString();
  const settlementId = generateUUID();

  try {
    await client.from('financial_settlements').insert({
      id: settlementId,
      period_type: periodType,
      start_date: nowStr,
      end_date: nowStr,
      total_income: totalIncome,
      total_payouts: totalPayouts,
      net_balance: netBalance,
      settled_by: currentAdminUser ? (currentAdminUser.name || currentAdminUser.email) : 'مدير النظام',
      notes: `تصفير الأرقام وتصفية الحسابات للفترة: ${periodType}`
    });

    const txIds = unsettleTx.map(t => t.id).filter(Boolean);
    if (txIds.length > 0) {
      await client.from('transactions').update({
        is_settled: true,
        settlement_id: settlementId
      }).in('id', txIds);
    }

    showToast(`✅ تم تصفير الأرقام وتصفية حسابات الفترة (${periodType}) بنجاح وتحويل المعاملات للأرشيف`);
    await loadFinancialDataFromSupabase();
    renderPage('wallet');
  } catch (err) {
    console.error('executePeriodReset error:', err);
    showToast(`❌ فشل التصفير: ${err.message}`);
  }
}

async function processTopupWithReceipt(userId, amount, methodCode, refCode, receiptBase64, notes) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client || !userId || !amount) return;

  try {
    const { data: usr } = await client.from('users').select('wallet_balance, name').eq('id', userId).maybeSingle();
    const currentBal = parseFloat(usr ? usr.wallet_balance || 0 : 0);
    const newBal = currentBal + parseFloat(amount);

    await client.from('users').update({ wallet_balance: newBal }).eq('id', userId);

    const txId = generateUUID();
    await client.from('transactions').insert({
      id: txId,
      user_id: userId,
      title: `شحن رصيد بواسطة ${methodCode || 'الإدارة'}`,
      amount: parseFloat(amount),
      type: 'charge',
      balance_after: newBal,
      payment_method: methodCode,
      reference_code: refCode || '',
      receipt_url: receiptBase64 || '',
      notes: notes || 'شحن رصيد وإرفاق إيصال التحويل',
      performed_by: currentAdminUser ? currentAdminUser.email : 'مدير النظام',
      created_at: new Date().toISOString()
    });

    // Push Notification + DB: إبلاغ المستخدم بشحن الرصيد المباشر
    try {
      await client.from('notifications').insert({
        id: generateUUID(),
        user_id: userId,
        title: '💰 تم شحن رصيدك',
        body: `تم شحن رصيد محفظتك بمبلغ ${parseFloat(amount)} ج.م بنجاح. رصيدك الحالي: ${newBal} ج.م`,
        type: 'wallet',
        created_at: new Date().toISOString()
      });
      await sendPushNotificationBackend({
        recipientId: userId,
        title: '💰 تم شحن رصيدك',
        body: `تم شحن رصيد محفظتك بمبلغ ${parseFloat(amount)} ج.م. رصيدك الحالي: ${newBal} ج.م`,
        type: 'wallet'
      });
    } catch (_) { }

    showToast('✅ تم شحن الرصيد وتوثيق الريسيت بنجاح');
    closeFinancialModal('rechargeModal');
    await loadFinancialDataFromSupabase();
    if (typeof window.runBulkSync === 'function') window.runBulkSync();
    renderPage('wallet');
  } catch (err) {
    showToast(`❌ خطأ في عملية الشحن: ${err.message}`);
  }
}

async function processDriverPayout(userId, amount, methodCode, refCode, receiptBase64, notes) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client || !userId || !amount) return;

  try {
    const { data: usr } = await client.from('users').select('wallet_balance, name').eq('id', userId).maybeSingle();
    const currentBal = parseFloat(usr ? usr.wallet_balance || 0 : 0);
    const payoutAmount = Math.abs(parseFloat(amount));
    const newBal = currentBal - payoutAmount;

    await client.from('users').update({ wallet_balance: newBal }).eq('id', userId);

    const txId = generateUUID();
    await client.from('transactions').insert({
      id: txId,
      user_id: userId,
      title: `سحب وتصفية مستحقات لسائق (${usr ? usr.name : ''})`,
      amount: -payoutAmount,
      type: 'deduction',
      balance_after: newBal,
      payment_method: methodCode,
      reference_code: refCode || '',
      receipt_url: receiptBase64 || '',
      notes: notes || 'تسوية وسحب مستحقات وإرفاق إثبات التحويل',
      performed_by: currentAdminUser ? currentAdminUser.email : 'مدير النظام',
      created_at: new Date().toISOString()
    });

    // Push Notification + DB: إبلاغ السائق بتحويل المستحقات
    try {
      await client.from('notifications').insert({
        id: generateUUID(),
        user_id: userId,
        title: '💳 تم تحويل مستحقاتك',
        body: `تم تحويل مبلغ ${payoutAmount} ج.م لحسابك. رصيدك الحالي: ${newBal} ج.م`,
        type: 'wallet',
        created_at: new Date().toISOString()
      });
      await sendPushNotificationBackend({
        recipientId: userId,
        title: '💳 تم تحويل مستحقاتك',
        body: `تم تحويل مبلغ ${payoutAmount} ج.م لحسابك. رصيدك الحالي: ${newBal} ج.م`,
        type: 'wallet',
        targetRole: 'driver'
      });
    } catch (_) { }

    showToast('✅ تم سحب المبلغ وتسوية المستحقات بنجاح');
    closeFinancialModal('payoutModal');
    await loadFinancialDataFromSupabase();
    if (typeof window.runBulkSync === 'function') window.runBulkSync();
    renderPage('wallet');
  } catch (err) {
    showToast(`❌ خطأ في عملية السحب والتسوية: ${err.message}`);
  }
}

async function addOrUpdatePaymentMethod(id, name, code, accountDetails, iconName) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client) return;

  try {
    if (id) {
      await client.from('payment_methods').update({
        name: name,
        account_details: accountDetails,
        icon_name: iconName,
        updated_at: new Date().toISOString()
      }).eq('id', id);
    } else {
      await client.from('payment_methods').insert({
        name: name,
        code: code || ('pm_' + Date.now()),
        account_details: accountDetails,
        icon_name: iconName || 'ri-bank-card-line',
        is_active: true
      });
    }

    showToast('✅ تم تحديث طريقة الدفع بنجاح');
    closeFinancialModal('paymentMethodsModal');
    await loadFinancialDataFromSupabase();
    if (typeof window.runBulkSync === 'function') window.runBulkSync();
    renderPage('wallet');
  } catch (err) {
    showToast(`❌ خطأ في حفظ طريقة الدفع: ${err.message}`);
  }
}

async function togglePaymentMethodActive(id, currentStatus) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client) return;
  try {
    await client.from('payment_methods').update({ is_active: !currentStatus }).eq('id', id);
    showToast('✅ تم تغيير حالة طريقة الدفع بالتطبيق');
    await loadFinancialDataFromSupabase();
    if (typeof window.runBulkSync === 'function') window.runBulkSync();
    renderPage('wallet');
  } catch (err) { }
}

async function deletePaymentMethod(id) {
  const client = getSupabaseClient() || supabaseClient;
  if (!client) return;
  if (!confirm('هل أنت تأكد من حذف طريقة الدفع هذه؟')) return;
  try {
    await client.from('payment_methods').delete().eq('id', id);
    showToast('✅ تم حذف طريقة الدفع');
    await loadFinancialDataFromSupabase();
    if (typeof window.runBulkSync === 'function') window.runBulkSync();
    renderPage('wallet');
  } catch (err) { }
}

function generateFinancialReport() {
  const periodTx = getFilteredTransactions();
  let totalIncome = 0;
  let totalExpense = 0;

  periodTx.forEach(t => {
    const amt = parseFloat(t.amount || 0);
    if (amt > 0) totalIncome += amt;
    else totalExpense += Math.abs(amt);
  });

  const netBalance = totalIncome - totalExpense;
  const periodNameMap = {
    'all': 'جميع الفترات الكلية',
    'today': 'تقرير اليوم المالي',
    'week': 'تقرير الأسبوع المالي',
    'month': 'تقرير الشهر المالي',
    'year': 'تقرير السنة المالية',
    'custom': 'تقرير الفترة المخصصة'
  };

  const reportTitle = periodNameMap[financialState.selectedPeriod] || 'التقرير المالي';
  const nowFormatted = new Date().toLocaleString('ar-EG');

  const printWindow = window.open('', '_blank', 'width=900,height=700');
  if (!printWindow) {
    showToast('⚠️ يرجى السماح بالنوافذ المنبثقة لإصدار التقرير');
    return;
  }

  const html = `
    <!DOCTYPE html>
    <html lang="ar" dir="rtl">
    <head>
      <meta charset="UTF-8">
      <title>${reportTitle} - inRide App</title>
      <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; padding: 24px; color: #111827; background: #fff; }
        .header { display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #1E88E5; padding-bottom: 16px; margin-bottom: 24px; }
        .logo { font-size: 24px; font-weight: bold; color: #1E88E5; }
        .title { font-size: 20px; font-weight: bold; text-align: center; margin-bottom: 20px; }
        .summary-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
        .summary-box { border: 1px solid #E5E7EB; border-radius: 8px; padding: 16px; text-align: center; }
        .summary-box.income { background: #ECFDF5; border-color: #10B981; }
        .summary-box.expense { background: #FEF2F2; border-color: #EF4444; }
        .summary-box.net { background: #EFF6FF; border-color: #3B82F6; }
        .summary-val { font-size: 20px; font-weight: bold; margin-top: 8px; }
        table { width: 100%; border-collapse: collapse; margin-top: 16px; font-size: 13px; }
        th, td { border: 1px solid #E5E7EB; padding: 10px; text-align: right; }
        th { background: #F9FAFB; font-weight: bold; }
        .badge { padding: 3px 8px; border-radius: 12px; font-size: 11px; font-weight: bold; }
        .badge-settled { background: #E0E7FF; color: #3730A3; }
        .badge-active { background: #D1FAE5; color: #065F46; }
        .footer { margin-top: 40px; text-align: center; font-size: 11px; color: #6B7280; border-top: 1px solid #E5E7EB; padding-top: 16px; }
        @media print { .no-print { display: none; } }
      </style>
    </head>
    <body>
      <div class="no-print" style="margin-bottom:20px;text-align:left;">
        <button onclick="window.print()" style="padding:10px 20px;background:#1E88E5;color:white;border:none;border-radius:6px;cursor:pointer;font-weight:bold;">🖨️ طباعة التقرير / حفظ كـ PDF</button>
      </div>
      <div class="header">
        <div class="logo">inRide Financial Statement</div>
        <div>تاريخ الإصدار: ${nowFormatted}</div>
      </div>
      <div class="title">${reportTitle}</div>
      <div class="summary-grid">
        <div class="summary-box income">
          <div>إجمالي التحويلات والإيرادات</div>
          <div class="summary-val">${totalIncome.toLocaleString()} ج.م</div>
        </div>
        <div class="summary-box expense">
          <div>إجمالي السحوبات والمصروفات</div>
          <div class="summary-val">${totalExpense.toLocaleString()} ج.م</div>
        </div>
        <div class="summary-box net">
          <div>صافي الرصيد للفترة</div>
          <div class="summary-val">${netBalance.toLocaleString()} ج.م</div>
        </div>
      </div>
      <h3>تفاصيل وحركات المعاملات المالية</h3>
      <table>
        <thead>
          <tr>
            <th>التاريخ والوقت</th>
            <th>البيان والتفاصيل</th>
            <th>طريقة الدفع والمرجع</th>
            <th>المبلغ</th>
            <th>الرصيد بعد</th>
            <th>حالة التصفية</th>
          </tr>
        </thead>
        <tbody>
          ${periodTx.length === 0 ? '<tr><td colspan="6" style="text-align:center;">لا توجد معاملات مسجلة لهذه الفترة</td></tr>' :
      periodTx.map(tx => {
        const amt = parseFloat(tx.amount || 0);
        const isInc = amt > 0;
        const dateStr = new Date(tx.created_at || Date.now()).toLocaleString('ar-EG');
        return `
                <tr>
                  <td>${dateStr}</td>
                  <td>
                    <strong>${tx.title || 'معاملة مالية'}</strong>
                    ${tx.notes ? `<div style="font-size:11px;color:#6B7280;">${tx.notes}</div>` : ''}
                  </td>
                  <td>${tx.payment_method || 'عادي'} ${tx.reference_code ? `(${tx.reference_code})` : ''}</td>
                  <td style="color:${isInc ? '#10B981' : '#EF4444'};font-weight:bold;">${isInc ? '+' : ''}${amt.toLocaleString()} ج.م</td>
                  <td>${parseFloat(tx.balance_after || 0).toLocaleString()} ج.م</td>
                  <td>
                    <span class="badge ${tx.is_settled ? 'badge-settled' : 'badge-active'}">
                      ${tx.is_settled ? 'مصفاة ومغلقة' : 'نشطة/جارية'}
                    </span>
                  </td>
                </tr>
              `;
      }).join('')
    }
        </tbody>
      </table>
      <div class="footer">
        تم استخراج هذا التقرير تلقائياً من نظام inRide Admin Dashboard - جميع الحقوق محفوظة © ${new Date().getFullYear()}
      </div>
    </body>
    </html>
  `;

  printWindow.document.write(html);
  printWindow.document.close();
}

function viewReceiptModal(receiptUrl, refCode, userName, amount, dateStr, pmName) {
  let modalEl = document.getElementById('receiptViewModal');
  if (!modalEl) {
    modalEl = document.createElement('div');
    modalEl.id = 'receiptViewModal';
    modalEl.className = 'modal-backdrop';
    document.body.appendChild(modalEl);
  }

  const amtNum = parseFloat(amount || 0);
  const amtFormatted = isNaN(amtNum) ? (amount || 0) : amtNum.toLocaleString();

  modalEl.style.display = 'flex';
  modalEl.innerHTML = `
    <div class="modal-content" style="max-width:550px;width:90%;border-radius:14px;padding:24px;background:white;position:relative;direction:rtl;box-shadow:0 20px 40px rgba(0,0,0,0.25);">
      <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #E5E7EB;padding-bottom:12px;margin-bottom:16px;">
        <h3 style="margin:0;font-size:16px;font-weight:800;color:var(--text-primary);">📸 ${refCode || 'معاينة إيصال التحويل ورسيت العملية'}</h3>
        <button class="btn btn-outline btn-sm" onclick="closeFinancialModal('receiptViewModal')" style="border-radius:50%;width:30px;height:30px;padding:0;">✕</button>
      </div>
      <div style="font-size:12px;color:var(--text-secondary);margin-bottom:16px;display:grid;grid-template-columns:1fr 1fr;gap:10px;background:#F8FAFC;padding:12px 14px;border-radius:10px;border:1px solid #E2E8F0;">
        <div><strong>👤 المستفيد:</strong> ${userName || 'غير محدد'}</div>
        <div><strong>💰 المبلغ:</strong> ${amtFormatted} ج.م</div>
        <div><strong>💳 طريقة الدفع:</strong> ${pmName || 'InstaPay'}</div>
        <div><strong>🧾 البيان / المرجع:</strong> ${refCode || 'إيصال تحويل'}</div>
        <div style="grid-column:span 2;"><strong>📅 التاريخ والوقت:</strong> ${dateStr || ''}</div>
      </div>
      <div style="text-align:center;background:#0F172A;padding:16px;border-radius:10px;max-height:380px;overflow:auto;">
        ${receiptUrl ?
      `<img src="${receiptUrl}" style="max-width:100%;max-height:340px;border-radius:8px;box-shadow:0 4px 14px rgba(0,0,0,0.4);object-fit:contain;" alt="الريسيت" onError="this.onerror=null;this.src='https://placehold.co/400x300?text=تعذر+تحميل+الصورة';" />` :
      `<div style="padding:32px;color:#94A3B8;"><i class="ri-file-unknow-line" style="font-size:48px;display:block;margin-bottom:8px;"></i><p style="margin:0;">لا توجد صورة ريسيت مرفقة لهذه المعاملة</p></div>`
    }
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:16px;">
        ${receiptUrl && receiptUrl.startsWith('http') ? `
          <a href="${receiptUrl}" download="receipt.png" target="_blank" class="btn btn-outline btn-sm" style="text-decoration:none;">
            <i class="ri-download-line"></i> فتح الصورة الكاملة
          </a>
        ` : '<div></div>'}
        <button class="btn btn-primary" onclick="closeFinancialModal('receiptViewModal')" style="padding:6px 20px;">إغلاق</button>
      </div>
    </div>
  `;
}

function closeReceiptModal() {
  closeFinancialModal('receiptViewModal');
  const oldModal = document.getElementById('receiptPreviewModal');
  if (oldModal) oldModal.style.display = 'none';
}

