// ============================================
// CAPTAIN DAILY MISSIONS PROGRESS TABLE
// ============================================
function getMissionDateHelper(dateOffsetDays = 0) {
  const d = new Date();
  if (dateOffsetDays !== 0) {
    d.setDate(d.getDate() + dateOffsetDays);
  }
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function formatRewardsMissionDate(dateStr) {
  if (!dateStr) return 'غير محدد';
  const todayStr = getMissionDateHelper(0);
  const yesterdayStr = getMissionDateHelper(-1);
  
  if (dateStr === todayStr) {
    return `اليوم (${dateStr})`;
  } else if (dateStr === yesterdayStr) {
    return `أمس (${dateStr})`;
  }
  
  try {
    const parts = dateStr.split('-');
    if (parts.length === 3) {
      const d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
      return d.toLocaleDateString('ar-EG', { weekday: 'long', year: 'numeric', month: 'short', day: 'numeric' });
    }
  } catch (e) {}
  return dateStr;
}

function formatRewardsMissionTime(isoStr) {
  if (!isoStr) return '--';
  try {
    const d = new Date(isoStr);
    return d.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });
  } catch (e) {
    return '--';
  }
}

function getFilteredRewardsMissions() {
  const todayStr = getMissionDateHelper(0);
  const yesterdayStr = getMissionDateHelper(-1);
  const weekAgoStr = getMissionDateHelper(-7);

  // Strictly only show captains who clicked "بدء التحدي" (is_started = true)
  let list = rewardsMissionsList.filter(m => m.is_started === true);

  // 1. Date Filter
  if (rewardsMissionsDateFilter === 'today') {
    list = list.filter(m => m.mission_date === todayStr);
  } else if (rewardsMissionsDateFilter === 'yesterday') {
    list = list.filter(m => m.mission_date === yesterdayStr);
  } else if (rewardsMissionsDateFilter === 'week') {
    list = list.filter(m => m.mission_date >= weekAgoStr);
  } else if (rewardsMissionsDateFilter === 'custom' && rewardsMissionsCustomDate) {
    list = list.filter(m => m.mission_date === rewardsMissionsCustomDate);
  }

  // 2. Status Filter
  if (rewardsMissionsStatusFilter === 'completed') {
    list = list.filter(m => m.is_completed || m.completed_trips >= m.target_trips);
  } else if (rewardsMissionsStatusFilter === 'pending_payout') {
    list = list.filter(m => (m.is_completed || m.completed_trips >= m.target_trips) && !m.is_rewarded);
  } else if (rewardsMissionsStatusFilter === 'in_progress') {
    // Only ongoing today
    list = list.filter(m => (m.mission_date >= todayStr) && !(m.is_completed || m.completed_trips >= m.target_trips));
  } else if (rewardsMissionsStatusFilter === 'incomplete') {
    // Expired past days without meeting target
    list = list.filter(m => (m.mission_date < todayStr) && !(m.is_completed || m.completed_trips >= m.target_trips));
  }

  // 3. Search Filter
  if (rewardsMissionsSearchQuery && rewardsMissionsSearchQuery.trim()) {
    const q = rewardsMissionsSearchQuery.trim().toLowerCase();
    list = list.filter(m => {
      const driverName = (m.driver?.name || '').toLowerCase();
      const driverPhone = (m.driver?.phone_number || m.driver?.phone || '').toLowerCase();
      const shiftTitle = (m.shift_title || '').toLowerCase();
      const dateStr = (m.mission_date || '').toLowerCase();
      return driverName.includes(q) || driverPhone.includes(q) || shiftTitle.includes(q) || dateStr.includes(q);
    });
  }

  // 4. Sort strictly from newest to oldest
  list.sort((a, b) => {
    const dateA = a.mission_date || '';
    const dateB = b.mission_date || '';
    if (dateA !== dateB) {
      return dateB.localeCompare(dateA);
    }
    const timeA = a.updated_at || a.created_at || '';
    const timeB = b.updated_at || b.created_at || '';
    return timeB.localeCompare(timeA);
  });

  return list;
}

function getRewardsMissionCounts() {
  const todayStr = getMissionDateHelper(0);
  const yesterdayStr = getMissionDateHelper(-1);
  const weekAgoStr = getMissionDateHelper(-7);

  const activeStartedList = rewardsMissionsList.filter(m => m.is_started === true);
  const totalAll = activeStartedList.length;
  const countToday = activeStartedList.filter(m => m.mission_date === todayStr).length;
  const countYesterday = activeStartedList.filter(m => m.mission_date === yesterdayStr).length;
  const countWeek = activeStartedList.filter(m => m.mission_date >= weekAgoStr).length;

  const countCompleted = activeStartedList.filter(m => m.is_completed || m.completed_trips >= m.target_trips).length;
  const countPendingPayout = activeStartedList.filter(m => (m.is_completed || m.completed_trips >= m.target_trips) && !m.is_rewarded).length;
  const countInProgress = activeStartedList.filter(m => (m.mission_date >= todayStr) && !(m.is_completed || m.completed_trips >= m.target_trips)).length;
  const countIncomplete = activeStartedList.filter(m => (m.mission_date < todayStr) && !(m.is_completed || m.completed_trips >= m.target_trips)).length;

  return { totalAll, countToday, countYesterday, countWeek, countCompleted, countPendingPayout, countInProgress, countIncomplete };
}

