function closeEditShiftModal() {
  const modal = document.getElementById('editShiftModal');
  if (modal) modal.style.display = 'none';
}

async function submitEditShift(shiftId) {
  const btn = document.getElementById('btnSubmitEditShift');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ri-loader-4-line ri-spin"></i> جاري الحفظ...'; }
  try {
    const title = document.getElementById('editShiftTitle')?.value.trim() || 'فترة مخصصة';
    const startVal = document.getElementById('editShiftStart')?.value || '06:00';
    const endVal = document.getElementById('editShiftEnd')?.value || '12:00';
    const target = parseInt(document.getElementById('editShiftTarget')?.value || 5, 10);
    const reward = parseFloat(document.getElementById('editShiftReward')?.value || 50);
    const isActive = document.getElementById('editShiftIsActive')?.checked ?? true;

    const { error } = await supabaseClient
      .from('driver_mission_shifts')
      .update({
        title: title,
        start_time: `${startVal}:00`,
        end_time: `${endVal}:00`,
        target_trips: target,
        reward_amount: reward,
        is_active: isActive,
        updated_at: new Date().toISOString()
      })
      .eq('id', shiftId);

    if (error) throw error;

    showToast('تم تعديل فترة البونص بنجاح وتزامنها مع التطبيق 🎉');
    closeEditShiftModal();
    await loadRewardsData(false);
  } catch (err) {
    console.error('Error updating shift:', err);
    showToast('فشل في تعديل الفترة: ' + err.message);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="ri-check-line"></i> حفظ التعديلات وتطبيقها'; }
  }
}

function showAddShiftModal() {
  let modal = document.getElementById('addShiftModal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'addShiftModal';
    modal.className = 'modal-overlay active';
    modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.5); z-index:9999; display:flex; align-items:center; justify-content:center; padding:20px;';
    document.body.appendChild(modal);
  }
  modal.style.display = 'flex';
  modal.innerHTML = `
    <div class="card" style="width:100%; max-width:500px; padding:24px; border-radius:var(--radius-xl); box-shadow:0 12px 40px rgba(0,0,0,0.25);">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; border-bottom:1px solid var(--border-color); padding-bottom:12px;">
        <h3 style="margin:0; font-size:16px; font-weight:800; display:flex; align-items:center; gap:8px;">
          <i class="ri-alarm-add-line" style="color:var(--medium-blue);"></i> إضافة فترة / شفت بونص جديد
        </h3>
        <button onclick="closeAddShiftModal()" style="background:none; border:none; font-size:20px; cursor:pointer; color:var(--text-light);">&times;</button>
      </div>

      <!-- Quick Preset Buttons -->
      <div style="margin-bottom:16px; background:var(--bg-primary); padding:10px 12px; border-radius:var(--radius-md); border:1px dashed var(--border-color);">
        <label style="font-size:11px; font-weight:800; color:var(--text-secondary); margin-bottom:6px; display:block;">قوالب سريعة جاهزة (اضغط للتعبئة الفورية):</label>
        <div style="display:flex; gap:6px; flex-wrap:wrap;">
          <button type="button" class="btn btn-sm btn-outline" onclick="applyShiftPreset('فترة الصباح', '06:00', '12:00', 5, 50)" style="font-size:11px; padding:3px 8px;">🌅 الصباح (06-12)</button>
          <button type="button" class="btn btn-sm btn-outline" onclick="applyShiftPreset('فترة الظهيرة', '12:00', '18:00', 5, 50)" style="font-size:11px; padding:3px 8px;">☀️ الظهيرة (12-18)</button>
          <button type="button" class="btn btn-sm btn-outline" onclick="applyShiftPreset('فترة المساء', '18:00', '23:59', 6, 60)" style="font-size:11px; padding:3px 8px;">🌙 المساء (18-24)</button>
          <button type="button" class="btn btn-sm btn-outline" onclick="applyShiftPreset('فترة الذروة', '13:00', '17:00', 4, 40)" style="font-size:11px; padding:3px 8px;">⚡ الذروة (13-17)</button>
        </div>
      </div>

      <form onsubmit="event.preventDefault(); submitNewShift();" style="display:flex; flex-direction:column; gap:16px;">
        <div class="form-group">
          <label style="font-weight:700; font-size:13px; margin-bottom:6px; display:block;">عنوان الفترة (مثلاً: فترة الصباح)</label>
          <input type="text" id="newShiftTitle" required placeholder="فترة الصباح" style="width:100%; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-md); background:var(--bg-primary);">
        </div>

        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
          <div class="form-group">
            <label style="font-weight:700; font-size:13px; margin-bottom:6px; display:block;">وقت البدء</label>
            <input type="time" id="newShiftStart" required value="06:00" style="width:100%; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-md); background:var(--bg-primary);">
          </div>
          <div class="form-group">
            <label style="font-weight:700; font-size:13px; margin-bottom:6px; display:block;">وقت الانتهاء</label>
            <input type="time" id="newShiftEnd" required value="12:00" style="width:100%; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-md); background:var(--bg-primary);">
          </div>
        </div>

        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px;">
          <div class="form-group">
            <label style="font-weight:700; font-size:13px; margin-bottom:6px; display:block;">الرحلات المطلوبة</label>
            <input type="number" id="newShiftTarget" min="1" step="1" required value="5" style="width:100%; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-md); background:var(--bg-primary);">
          </div>
          <div class="form-group">
            <label style="font-weight:700; font-size:13px; margin-bottom:6px; display:block;">مبلغ البونص (ج.م)</label>
            <input type="number" id="newShiftReward" min="0" step="5" required value="50" style="width:100%; padding:10px; border:1px solid var(--border-color); border-radius:var(--radius-md); background:var(--bg-primary);">
          </div>
        </div>

        <div style="display:flex; justify-content:flex-end; gap:10px; margin-top:12px; border-top:1px solid var(--border-color); padding-top:16px;">
          <button type="button" class="btn btn-outline" onclick="closeAddShiftModal()">إلغاء</button>
          <button type="submit" class="btn btn-primary" id="btnSubmitNewShift">
            <i class="ri-check-line"></i> حفظ الفترة وتفعيلها
          </button>
        </div>
      </form>
    </div>
  `;
}

window.applyShiftPreset = function(title, start, end, trips, reward) {
  const t = document.getElementById('newShiftTitle');
  const s = document.getElementById('newShiftStart');
  const e = document.getElementById('newShiftEnd');
  const tr = document.getElementById('newShiftTarget');
  const r = document.getElementById('newShiftReward');
  if (t) t.value = title;
  if (s) s.value = start;
  if (e) e.value = end;
  if (tr) tr.value = trips;
  if (r) r.value = reward;
};

function closeAddShiftModal() {
  const modal = document.getElementById('addShiftModal');
  if (modal) modal.style.display = 'none';
}

async function submitNewShift() {
  const btn = document.getElementById('btnSubmitNewShift');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ri-loader-4-line ri-spin"></i> جاري الحفظ...'; }
  try {
    const title = document.getElementById('newShiftTitle')?.value.trim() || 'فترة مخصصة';
    const startVal = document.getElementById('newShiftStart')?.value || '06:00';
    const endVal = document.getElementById('newShiftEnd')?.value || '12:00';
    const target = parseInt(document.getElementById('newShiftTarget')?.value || 5, 10);
    const reward = parseFloat(document.getElementById('newShiftReward')?.value || 50);

    const { error } = await supabaseClient
      .from('driver_mission_shifts')
      .insert({
        title: title,
        start_time: `${startVal}:00`,
        end_time: `${endVal}:00`,
        target_trips: target,
        reward_amount: reward,
        is_active: true
      });

    if (error) throw error;
    showToast('تمت إضافة فترة البونص بنجاح 🎉');
    closeAddShiftModal();
    await loadRewardsData(false);
  } catch (err) {
    console.error('Error saving shift:', err);
    showToast('فشل في إضافة الفترة: ' + err.message);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="ri-check-line"></i> حفظ الفترة وتفعيلها'; }
  }
}

async function handleToggleShiftActive(shiftId, active, elem) {
  if (elem) {
    const pill = elem.closest('td')?.querySelector('.switch-pill');
    if (pill) {
      pill.className = active ? 'switch-pill active' : 'switch-pill inactive';
      pill.textContent = active ? 'مفعل 🟢' : 'متوقف ⚪';
    }
  }
  try {
    const { error } = await supabaseClient
      .from('driver_mission_shifts')
      .update({ is_active: active, updated_at: new Date().toISOString() })
      .eq('id', shiftId);
    if (error) throw error;
    showToast(active ? 'تم تفعيل الفترة بنجاح 🟢' : 'تم تعطيل الفترة ⏸️');
    await loadRewardsData(false);
  } catch (err) {
    console.error('Error toggling shift active:', err);
    showToast('فشل تعديل حالة الفترة: ' + err.message);
  }
}

async function handleDeleteShift(shiftId) {
  if (!confirm('هل أنت متأكد من حذف فترة البونص هذه؟')) return;
  try {
    const { error } = await supabaseClient
      .from('driver_mission_shifts')
      .delete()
      .eq('id', shiftId);
    if (error) throw error;
    showToast('تم حذف فترة البونص بنجاح 🗑️');
    await loadRewardsData(false);
  } catch (err) {
    console.error('Error deleting shift:', err);
    showToast('فشل حذف الفترة: ' + err.message);
  }
}

// ============================================
// CAPTAIN PROFILE MISSION & BONUS PROGRESS CARD
// ============================================
async function loadCaptainMissionCard(uid, role = 'driver') {
  const container = document.getElementById('profileCaptainMissionCardContainer');
  if (!container) return;

  // Challenges and daily missions are strictly for drivers/captains, never riders/passengers
  if (role !== 'driver') {
    container.innerHTML = '';
    container.style.display = 'none';
    return;
  }

  try {
    if (!supabaseClient) {
      container.style.display = 'none';
      return;
    }

    // Call get_active_driver_mission RPC
    const { data: mission, error } = await supabaseClient.rpc('get_active_driver_mission', { p_driver_id: uid });
    if (error || !mission || (!mission.is_active && !mission.has_active_mission)) {
      if (role === 'rider') {
        container.innerHTML = '';
        container.style.display = 'none';
        return;
      }
      container.style.display = 'block';
      container.innerHTML = `
        <div class="card" style="padding:16px 20px; background:var(--bg-primary); border:1px dashed var(--border-color); border-radius:var(--radius-xl); display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:20px;">
          <div style="display:flex; align-items:center; gap:10px;">
            <i class="ri-information-line" style="font-size:22px; color:var(--text-light);"></i>
            <span style="font-size:13px; color:var(--text-secondary); font-weight:600;">لا يوجد بونص أو تحدي يومي نشط لهذا الكابتن في هذا الوقت.</span>
          </div>
          <button class="btn btn-outline btn-sm" onclick="navigateTo('rewards')" style="font-size:11px;">إدارة التحديات والبونص</button>
        </div>
      `;
      return;
    }

    container.style.display = 'block';
    const isCompleted = mission.is_completed || (mission.completed_trips >= mission.target_trips);
    const target = mission.target_trips || 10;
    const done = mission.completed_trips || 0;
    const remaining = mission.remaining_trips !== undefined ? mission.remaining_trips : Math.max(0, target - done);
    const progressPct = Math.min(100, Math.round((done / Math.max(1, target)) * 100));
    const title = mission.title || 'تحدي اليوم 🚀';
    const timeWindow = mission.time_window_text || (mission.start_time && mission.end_time ? `من ${mission.start_time} إلى ${mission.end_time}` : 'طوال اليوم (حتى 11:59 م)');
    const reward = parseFloat(mission.reward_amount || 50);

    container.innerHTML = `
      <div class="card rewards-hero-card" style="background:linear-gradient(135deg, ${isCompleted ? '#065F46 0%, #059669 100%' : (mission.is_shift ? '#0F2042 0%, #1E3A8A 50%, #2563EB 100%' : '#0F172A 0%, #1E293B 100%')} !important; color:#fff !important; padding:22px; border-radius:var(--radius-xl); box-shadow:0 10px 25px ${isCompleted ? 'rgba(5,150,105,0.25)' : 'rgba(37,99,235,0.25)'}; position:relative; overflow:hidden; border:1px solid ${isCompleted ? '#34D399' : 'rgba(255,255,255,0.2)'} !important; margin-bottom:20px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:16px; flex-wrap:wrap;">
          
          <!-- Left: Icon and Header Info -->
          <div style="display:flex; align-items:center; gap:14px; flex:1; min-width:260px;">
            <div style="width:48px; height:48px; border-radius:50%; background:${isCompleted ? 'rgba(253,224,71,0.25)' : 'rgba(255,255,255,0.15)'}; display:flex; align-items:center; justify-content:center; font-size:26px; color:#FDE047; border:2px solid ${isCompleted ? '#FDE047' : 'rgba(255,255,255,0.2)'}; flex-shrink:0;">
              <i class="${isCompleted ? 'ri-medal-fill' : (mission.is_shift ? 'ri-time-fill' : 'ri-trophy-fill')}"></i>
            </div>
            <div>
              <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
                <h4 style="margin:0; font-size:16px; font-weight:800; color:#fff;">${title} ${isCompleted ? '(مكتمل) 🏆' : ''}</h4>
                <span style="background:${isCompleted ? '#047857' : 'rgba(16,185,129,0.3)'}; border:1px solid #34D399; color:#fff; padding:2px 8px; border-radius:8px; font-size:10px; font-weight:700;">
                  ${isCompleted ? 'تم صرف البونص 🏆' : 'نشط للكابتن الآن 🟢'}
                </span>
              </div>
              <div style="margin-top:4px; display:inline-flex; align-items:center; gap:5px; background:rgba(0,0,0,0.25); padding:3px 10px; border-radius:6px; font-size:11px; font-weight:700; color:#FDE047;">
                <i class="ri-alarm-line"></i>
                <span>المواعيد: ${timeWindow}</span>
              </div>
            </div>
          </div>

          <!-- Right: Reward Amount Pill -->
          <div style="text-align:center; background:linear-gradient(135deg, #FDE047 0%, #F59E0B 100%); color:#0F172A; padding:8px 16px; border-radius:14px; font-weight:900; box-shadow:0 4px 12px rgba(245,158,11,0.35);">
            <div style="font-size:16px; font-family:'Outfit',sans-serif; line-height:1.1;">+${reward.toFixed(0)} ج.م</div>
            <div style="font-size:10px; font-weight:800;">بونص كاش</div>
          </div>
        </div>

        <!-- Progress highlight box (User requirement: أنجز كذا وفاضل كذا) -->
        <div style="margin:16px 0 12px 0; background:${isCompleted ? 'rgba(255,255,255,0.18)' : 'rgba(255,255,255,0.1)'}; padding:10px 14px; border-radius:12px; border:1px solid rgba(255,255,255,0.15); display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:8px;">
          <div style="display:flex; align-items:center; gap:8px;">
            <i class="${isCompleted ? 'ri-checkbox-circle-fill' : 'ri-flag-fill'}" style="color:${isCompleted ? '#FDE047' : '#60A5FA'}; font-size:18px;"></i>
            <span style="font-size:13px; font-weight:700; color:#fff;">
              ${isCompleted
        ? 'تهانينا للكابتن! حقق التحدي بنجاح وتم إيداع المكافأة في محفظته 🎉'
        : `أنجز الكابتن <strong>${done}</strong> من <strong>${target}</strong> رحلات — <span style="color:#FDE047; font-weight:800;">فاضل ${remaining} رحلات</span> للحصول على البونص! 🚀`}
            </span>
          </div>
          <button onclick="loadCaptainMissionCard('${uid}', '${role}')" title="تحديث حالة التحدي" style="background:rgba(255,255,255,0.2); border:none; color:#fff; border-radius:6px; padding:4px 8px; cursor:pointer; font-size:11px; display:inline-flex; align-items:center; gap:4px;">
            <i class="ri-refresh-line"></i> تحديث
          </button>
        </div>

        <!-- Progress Bar -->
        <div style="background:rgba(255,255,255,0.2); height:10px; border-radius:6px; overflow:hidden; margin-bottom:8px;">
          <div style="background:${isCompleted ? '#FDE047' : '#38BDF8'}; height:100%; width:${progressPct}%; transition:width 0.4s ease; border-radius:6px;"></div>
        </div>

        <!-- Progress Footer -->
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:11px; color:rgba(255,255,255,0.9); font-weight:700;">
          <span>${isCompleted ? '100% تم الإنجاز 🏆' : `${progressPct}% من الهدف المطلوب`}</span>
          <span style="font-family:'Outfit',sans-serif; font-size:13px; color:#fff;">${done} / ${target} رحلة مكتملة</span>
        </div>
      </div>
    `;
  } catch (err) {
    console.error('Error loading captain mission card:', err);
    if (container) container.style.display = 'none';
  }
}

// ============================================
// TRIP REPORTS & COMPLAINTS SYSTEM (Realtime Supabase)
// ============================================
let liveTripReports = [];
let reportSearchQuery = '';
let reportFilterStatus = 'all'; // 'all', 'pending', 'investigating', 'resolved', 'dismissed'

async function loadReportsFromSupabase() {
  if (!supabaseClient) return;
  try {
    const { data: reports, error } = await supabaseClient
      .from('trip_reports')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      console.error('[Reports] Error loading trip_reports:', error);
      return;
    }

    liveTripReports = reports || [];
    updateReportsBadge();

    if (currentPage === 'reports') {
      const container = document.getElementById('pageContent');
      if (container) {
        container.innerHTML = renderReportsPage();
      }
    }
  } catch (err) {
    console.error('[Reports] Exception loading trip_reports:', err);
  }
}

function updateReportsBadge() {
  const pendingCount = (liveTripReports || []).filter(r => r.status === 'pending').length;
  const badgeEl = document.getElementById('reportsBadge');
  if (badgeEl) {
    if (pendingCount > 0) {
      badgeEl.textContent = pendingCount;
      badgeEl.style.display = 'inline-block';
    } else {
      badgeEl.style.display = 'none';
    }
  }
}

function setReportFilter(status) {
  reportFilterStatus = status;
  if (currentPage === 'reports') {
    const container = document.getElementById('pageContent');
    if (container) {
      container.innerHTML = renderReportsPage();
    }
  }
}

function handleReportSearch(query) {
  reportSearchQuery = (query || '').toLowerCase().trim();
  const tableBody = document.getElementById('reportsTableBody');
  if (tableBody) {
    tableBody.innerHTML = renderReportsTableRows();
  }
}

async function updateReportStatus(reportId, newStatus) {
  if (!supabaseClient || !reportId) return;
  try {
    const updatePayload = {
      status: newStatus,
      updated_at: new Date().toISOString()
    };
    if (newStatus === 'resolved') {
      updatePayload.resolved_at = new Date().toISOString();
    }

    const { error } = await supabaseClient
      .from('trip_reports')
      .update(updatePayload)
      .eq('id', reportId);

    if (error) {
      showToast('❌ تعذر تحديث حالة البلاغ: ' + error.message);
      return;
    }

    showToast(newStatus === 'resolved' ? '✅ تم إغلاق وحل البلاغ بنجاح' : '⏳ تم تحديث حالة البلاغ');
    await loadReportsFromSupabase();
  } catch (e) {
    showToast('❌ حدث خطأ: ' + e.message);
  }
}

async function promptReportAdminNotes(reportId, currentNotes = '') {
  if (!supabaseClient || !reportId) return;
  const note = prompt('إضافة ملاحظات وتوجيهات الإدارة لهذا البلاغ:', currentNotes || '');
  if (note === null) return;

  try {
    const { error } = await supabaseClient
      .from('trip_reports')
      .update({
        admin_notes: note,
        updated_at: new Date().toISOString()
      })
      .eq('id', reportId);

    if (error) {
      showToast('❌ فشل حفظ ملاحظات الإدارة: ' + error.message);
      return;
    }

    showToast('✅ تم حفظ ملاحظات الإدارة بنجاح');
    await loadReportsFromSupabase();
  } catch (e) {
    showToast('❌ حدث خطأ: ' + e.message);
  }
}

function renderReportsPage() {
  const reports = liveTripReports || [];
  const totalCount = reports.length;
  const pendingCount = reports.filter(r => r.status === 'pending').length;
  const investigatingCount = reports.filter(r => r.status === 'investigating').length;
  const resolvedCount = reports.filter(r => r.status === 'resolved').length;
  const dismissedCount = reports.filter(r => r.status === 'dismissed').length;

  return `
    <div class="page-section">
      <!-- Header -->
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;flex-wrap:wrap;gap:12px;">
        <div>
          <h2 style="font-size:22px;font-weight:800;margin-bottom:4px;color:var(--text-primary);">
            <i class="ri-alarm-warning-fill" style="color:#EF4444;margin-left:8px;"></i>
            سجل بلاغات وشكاوى الرحلات (Realtime Supabase)
          </h2>
          <p style="font-size:13px;color:var(--text-secondary);margin:0;">
            متابعة البلاغات والشكاوى المقدمة من الركاب والكباتن أثناء سير الرحلة، بعد انتهائها، أو عند إلغائها
          </p>
        </div>
        <div style="display:flex;gap:8px;">
          <button class="btn btn-outline btn-sm" onclick="loadReportsFromSupabase()">
            <i class="ri-refresh-line"></i> تحديث البلاغات
          </button>
        </div>
      </div>

      <!-- KPI Stats Grid -->
      <div class="stats-grid" style="margin-bottom:24px;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));">
        <div class="stat-card blue">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-shield-fill"></i></div>
          </div>
          <div class="stat-card-value font-outfit">${totalCount}</div>
          <div class="stat-card-label">إجمالي البلاغات الواردة</div>
        </div>

        <div class="stat-card red">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-error-warning-fill"></i></div>
          </div>
          <div class="stat-card-value font-outfit" style="color:#EF4444;">${pendingCount}</div>
          <div class="stat-card-label">بلاغات جديدة معلقة 🔴</div>
        </div>

        <div class="stat-card orange">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-time-fill"></i></div>
          </div>
          <div class="stat-card-value font-outfit" style="color:#F59E0B;">${investigatingCount}</div>
          <div class="stat-card-label">قيد المتابعة والتحقيق ⏳</div>
        </div>

        <div class="stat-card green">
          <div class="stat-card-header">
            <div class="stat-card-icon"><i class="ri-checkbox-circle-fill"></i></div>
          </div>
          <div class="stat-card-value font-outfit" style="color:#10B981;">${resolvedCount}</div>
          <div class="stat-card-label">تمت معالجتها وحلها ✅</div>
        </div>
      </div>

      <!-- Filters & Search Bar -->
      <div class="card" style="margin-bottom:20px;">
        <div class="card-body" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:14px;padding:16px;">
          <div style="display:flex;gap:6px;flex-wrap:wrap;background:var(--bg-primary);padding:4px;border-radius:var(--radius-md);">
            <button class="btn btn-sm ${reportFilterStatus === 'all' ? 'btn-primary' : 'btn-outline'}" onclick="setReportFilter('all')">الكل (${totalCount})</button>
            <button class="btn btn-sm ${reportFilterStatus === 'pending' ? 'btn-primary' : 'btn-outline'}" onclick="setReportFilter('pending')">جديدة معلقة (${pendingCount})</button>
            <button class="btn btn-sm ${reportFilterStatus === 'investigating' ? 'btn-primary' : 'btn-outline'}" onclick="setReportFilter('investigating')">قيد المتابعة (${investigatingCount})</button>
            <button class="btn btn-sm ${reportFilterStatus === 'resolved' ? 'btn-primary' : 'btn-outline'}" onclick="setReportFilter('resolved')">تم الحل (${resolvedCount})</button>
            <button class="btn btn-sm ${reportFilterStatus === 'dismissed' ? 'btn-primary' : 'btn-outline'}" onclick="setReportFilter('dismissed')">متجاهلة (${dismissedCount})</button>
          </div>

          <div style="flex:1;max-width:380px;min-width:240px;position:relative;">
            <input type="text" id="reportSearchInput" value="${escapeHtml(reportSearchQuery)}" placeholder="بحث بالاسم، الهاتف، رقم الرحلة، أو السبب..." style="width:100%;padding:8px 34px 8px 12px;border:1px solid var(--border-color);border-radius:var(--radius-md);background:var(--bg-primary);font-size:13px;" oninput="handleReportSearch(this.value)">
            <i class="ri-search-line" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);color:var(--text-light);"></i>
          </div>
        </div>
      </div>

      <!-- Reports List / Table Card -->
      <div class="card">
        <div class="card-header" style="display:flex;justify-content:space-between;align-items:center;padding:16px;">
          <h3 style="margin:0;font-size:15px;font-weight:700;">
            <i class="ri-file-list-3-line text-blue"></i> تفاصيل البلاغات والأطراف المعنية
          </h3>
        </div>
        <div class="card-body" style="padding:0;">
          <div class="table-responsive">
            <table class="data-table" style="width:100%;font-size:12px;">
              <thead>
                <tr style="background:var(--bg-primary);">
                  <th style="padding:12px 14px;">طرفا البلاغ</th>
                  <th style="padding:12px 14px;">الرحلة المعنية</th>
                  <th style="padding:12px 14px;">حساب الراكب</th>
                  <th style="padding:12px 14px;">حساب الكابتن</th>
                  <th style="padding:12px 14px;min-width:220px;">الرسالة وتفاصيل البلاغ</th>
                  <th style="padding:12px 14px;">الحالة</th>
                  <th style="padding:12px 14px;text-align:center;">إجراءات الإدارة</th>
                </tr>
              </thead>
              <tbody id="reportsTableBody">
                ${renderReportsTableRows()}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  `;
}

function renderReportsTableRows() {
  let list = liveTripReports || [];

  if (reportFilterStatus !== 'all') {
    list = list.filter(r => r.status === reportFilterStatus);
  }

  if (reportSearchQuery) {
    const q = reportSearchQuery.toLowerCase();
    list = list.filter(r => {
      const pName = (r.passenger_name || '').toLowerCase();
      const pPhone = (r.passenger_phone || '').toLowerCase();
      const dName = (r.driver_name || '').toLowerCase();
      const dPhone = (r.driver_phone || '').toLowerCase();
      const reason = (r.reason || '').toLowerCase();
      const desc = (r.description || '').toLowerCase();
      const tripId = (r.trip_id || '').toLowerCase();
      return pName.includes(q) || pPhone.includes(q) || dName.includes(q) || dPhone.includes(q) || reason.includes(q) || desc.includes(q) || tripId.includes(q);
    });
  }

  if (list.length === 0) {
    return `
      <tr>
        <td colspan="7" style="text-align:center;padding:40px;color:var(--text-light);">
          <i class="ri-shield-check-line" style="font-size:36px;color:#10B981;display:block;margin-bottom:8px;"></i>
          لا توجد بلاغات مسجلة مطابقة لهذا التصنيف
        </td>
      </tr>
    `;
  }

  return list.map(r => {
    const isPassengerReporter = r.reporter_role === 'passenger';
    const timeStr = r.created_at ? new Date(r.created_at).toLocaleString('ar-EG') : '—';

    let statusBadge = '';
    if (r.status === 'pending') {
      statusBadge = '<span class="badge" style="background:#FEE2E2;color:#991B1B;font-weight:700;padding:4px 10px;border-radius:12px;">معلق / جديد 🔴</span>';
    } else if (r.status === 'investigating') {
      statusBadge = '<span class="badge" style="background:#FEF3C7;color:#92400E;font-weight:700;padding:4px 10px;border-radius:12px;">قيد المتابعة ⏳</span>';
    } else if (r.status === 'resolved') {
      statusBadge = '<span class="badge" style="background:#D1FAE5;color:#065F46;font-weight:700;padding:4px 10px;border-radius:12px;">تم الحل ✅</span>';
    } else {
      statusBadge = '<span class="badge" style="background:#F3F4F6;color:#4B5563;font-weight:700;padding:4px 10px;border-radius:12px;">تم التجاهل ⚪</span>';
    }

    let tripStatusLabel = '';
    if (r.trip_status === 'in_progress') {
      tripStatusLabel = '<span class="badge" style="background:#EFF6FF;color:#1D4ED8;font-size:10px;">أثناء سير الرحلة 🚗</span>';
    } else if (r.trip_status === 'completed') {
      tripStatusLabel = '<span class="badge" style="background:#ECFDF5;color:#047857;font-size:10px;">بعد اكتمال الرحلة ✅</span>';
    } else if (r.trip_status === 'cancelled') {
      tripStatusLabel = '<span class="badge" style="background:#FFF1F2;color:#BE123C;font-size:10px;">بعد إلغاء الرحلة ❌</span>';
    } else {
      tripStatusLabel = `<span class="badge" style="background:#F3F4F6;color:#374151;font-size:10px;">${escapeHtml(r.trip_status || 'مشوار')}</span>`;
    }

    const shortTripId = r.trip_id ? r.trip_id.substring(0, 8) : 'غير محدد';

    return `
      <tr style="border-bottom:1px solid var(--border-light);vertical-align:top;">
        <td style="padding:14px;">
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">
            ${isPassengerReporter
              ? '<span class="badge" style="background:#F3E8FF;color:#7E22CE;font-weight:700;font-size:11px;">👤 الراكب أبلغ عن الكابتن</span>'
              : '<span class="badge" style="background:#E0F2FE;color:#0369A1;font-weight:700;font-size:11px;">🚗 الكابتن أبلغ عن الراكب</span>'}
          </div>
          <div style="font-size:11px;color:var(--text-light);"><i class="ri-time-line"></i> ${timeStr}</div>
        </td>

        <td style="padding:14px;">
          <div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">
            <span style="font-family:monospace;font-size:11px;background:#F3F4F6;padding:2px 6px;border-radius:4px;font-weight:bold;">#${shortTripId}</span>
            ${tripStatusLabel}
          </div>
          <div style="font-size:11px;line-height:1.4;margin-bottom:4px;">
            <div><i class="ri-map-pin-2-fill" style="color:var(--medium-blue);font-size:10px;"></i> <b>من:</b> ${escapeHtml(r.pickup_address || 'الموقع المسجل')}</div>
            <div><i class="ri-flag-fill" style="color:var(--dark-blue);font-size:10px;"></i> <b>إلى:</b> ${escapeHtml(r.destination_address || 'الوجهة المسجلة')}</div>
          </div>
          ${r.fare ? `<div style="font-size:11px;font-weight:700;color:var(--medium-blue);">${r.fare} ج.م</div>` : ''}
        </td>

        <td style="padding:14px;">
          <div style="font-weight:700;color:var(--text-primary);display:flex;align-items:center;gap:4px;">
            <i class="ri-user-line" style="color:#7E22CE;"></i>
            ${escapeHtml(r.passenger_name || 'راكب inRide')}
          </div>
          <div style="font-size:11px;color:var(--text-secondary);direction:ltr;text-align:right;margin:2px 0 6px 0;">
            ${escapeHtml(r.passenger_phone || '—')}
          </div>
          <div style="display:flex;gap:4px;flex-wrap:wrap;">
            ${r.passenger_phone ? `
              <a href="tel:${r.passenger_phone}" class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" title="اتصال">
                <i class="ri-phone-line"></i> اتصال
              </a>
            ` : ''}
            ${r.passenger_id ? `
              <button class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" onclick="openDirectUserChat('${r.passenger_id}', '${escapeHtml(r.passenger_name || 'الراكب')}', 'rider')" title="محادثة مباشرة">
                <i class="ri-chat-3-line"></i> شات
              </button>
              <button class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" onclick="viewUserProfile('${r.passenger_id}', 'rider')" title="عرض الملف">
                <i class="ri-external-link-line"></i> الملف
              </button>
            ` : ''}
          </div>
        </td>

        <td style="padding:14px;">
          <div style="font-weight:700;color:var(--text-primary);display:flex;align-items:center;gap:4px;">
            <i class="ri-steering-2-fill" style="color:#0369A1;"></i>
            ${escapeHtml(r.driver_name || 'كابتن inRide')}
          </div>
          <div style="font-size:11px;color:var(--text-secondary);direction:ltr;text-align:right;margin:2px 0 6px 0;">
            ${escapeHtml(r.driver_phone || '—')}
          </div>
          <div style="display:flex;gap:4px;flex-wrap:wrap;">
            ${r.driver_phone ? `
              <a href="tel:${r.driver_phone}" class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" title="اتصال">
                <i class="ri-phone-line"></i> اتصال
              </a>
            ` : ''}
            ${r.driver_id ? `
              <button class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" onclick="openDirectUserChat('${r.driver_id}', '${escapeHtml(r.driver_name || 'الكابتن')}', 'driver')" title="محادثة مباشرة">
                <i class="ri-chat-3-line"></i> شات
              </button>
              <button class="btn btn-sm btn-outline" style="padding:2px 6px;font-size:10px;" onclick="viewUserProfile('${r.driver_id}', 'driver')" title="عرض الملف">
                <i class="ri-external-link-line"></i> الملف
              </button>
            ` : ''}
          </div>
        </td>

        <td style="padding:14px;">
          <div style="font-weight:700;color:#DC2626;font-size:12px;margin-bottom:6px;">
            <i class="ri-error-warning-line"></i> ${escapeHtml(r.reason)}
          </div>
          <div style="font-size:12px;color:var(--text-primary);background:#F9FAFB;padding:8px;border-radius:8px;border:1px solid var(--border-light);line-height:1.5;">
            ${escapeHtml(r.description || 'لا توجد تفاصيل إضافية مكتوبة.')}
          </div>
          ${r.admin_notes ? `
            <div style="margin-top:6px;font-size:11px;color:#047857;background:#ECFDF5;padding:6px;border-radius:6px;border:1px solid #A7F3D0;">
              <b>ملاحظة الإدارة:</b> ${escapeHtml(r.admin_notes)}
            </div>
          ` : ''}
        </td>

        <td style="padding:14px;white-space:nowrap;">
          ${statusBadge}
          ${r.resolved_at ? `<div style="font-size:10px;color:var(--text-light);margin-top:4px;">حُل في: ${new Date(r.resolved_at).toLocaleDateString('ar-EG')}</div>` : ''}
        </td>

        <td style="padding:14px;text-align:center;">
          <div style="display:flex;flex-direction:column;gap:5px;align-items:center;">
            ${r.status === 'pending' ? `
              <button class="btn btn-sm btn-primary" style="width:100%;font-size:11px;" onclick="updateReportStatus('${r.id}', 'investigating')">
                <i class="ri-time-line"></i> بدء المتابعة
              </button>
            ` : ''}
            ${r.status !== 'resolved' ? `
              <button class="btn btn-sm btn-success" style="width:100%;font-size:11px;background:#10B981;color:#fff;" onclick="updateReportStatus('${r.id}', 'resolved')">
                <i class="ri-check-line"></i> تم الحل
              </button>
            ` : ''}
            ${r.status !== 'dismissed' && r.status !== 'resolved' ? `
              <button class="btn btn-sm btn-outline" style="width:100%;font-size:11px;color:#6B7280;" onclick="updateReportStatus('${r.id}', 'dismissed')">
                <i class="ri-close-circle-line"></i> تجاهل
              </button>
            ` : ''}
            <button class="btn btn-sm btn-outline" style="width:100%;font-size:11px;" onclick="promptReportAdminNotes('${r.id}', '${escapeHtml(r.admin_notes || '')}')">
              <i class="ri-edit-line"></i> ملاحظة إدارية
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

// =============================================================================
// PROMO CODES & BARCODE GENERATOR SYSTEM (inRide Brand Edition)
// =============================================================================

let promoCodesList = [];
let promoCodesFilterStatus = 'all'; // 'all', 'active', 'paused', 'expired'
let promoCodesSearchQuery = '';
let promoCodesRealtimeChannel = null;
let activeEditingPromoId = null;

/**
 * Generates an authentic SVG Barcode in pure JS
 */
function generateBarcodeSVG(code, width = 200, height = 50, showText = true) {
  if (!code) code = 'INRIDE';
  const clean = String(code).toUpperCase().replace(/[^A-Z0-9_-]/g, '');
  
  let bars = [2, 1, 2, 1]; // start quiet / guard
  for (let i = 0; i < clean.length; i++) {
    const c = clean.charCodeAt(i);
    const w1 = (c % 3) + 1;
    const w2 = ((c >> 1) % 2) + 1;
    const w3 = ((c >> 2) % 3) + 1;
    const w4 = ((c >> 3) % 2) + 1;
    bars.push(w1, w2, w3, w4);
  }
  bars.push(2, 1, 1, 2, 3); // stop guard

  const totalUnits = bars.reduce((acc, v) => acc + v, 0);
  const unitWidth = (width - 16) / totalUnits;
  const barHeight = showText ? height - 16 : height;

  let x = 8;
  let rects = '';
  for (let i = 0; i < bars.length; i++) {
    const w = bars[i] * unitWidth;
    if (i % 2 === 0) {
      rects += `<rect x="${x.toFixed(1)}" y="3" width="${w.toFixed(1)}" height="${barHeight}" fill="#0F172A" rx="0.5" />`;
    }
    x += w;
  }

  const textElement = showText ? `
    <text x="${(width / 2).toFixed(1)}" y="${height - 2}" text-anchor="middle" font-family="'Courier New', Courier, monospace" font-size="10.5" font-weight="bold" fill="#334155" letter-spacing="1.5">
      ${clean}
    </text>
  ` : '';

  return `
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" style="display:block;">
      ${rects}
      ${textElement}
    </svg>
  `;
}

function generateRandomPromoCode() {
  const prefixes = ['INRIDE', 'RIDE', 'SADAT', 'BONUS', 'VIP', 'OFFER', 'SUPER'];
  const numbers = ['20', '25', '50', '100', '2026', '77', '99'];
  const p = prefixes[Math.floor(Math.random() * prefixes.length)];
  const n = numbers[Math.floor(Math.random() * numbers.length)];
  const input = document.getElementById('inputPromoCode');
  if (input) {
    input.value = `${p}${n}`;
    updateModalBarcodePreview();
  }
}

function updateModalBarcodePreview() {
  const codeVal = document.getElementById('inputPromoCode')?.value?.trim() || 'INRIDE50';
  const preview = document.getElementById('modalBarcodePreviewContainer');
  if (preview) {
    preview.innerHTML = generateBarcodeSVG(codeVal, 240, 60, true);
  }
}

